const section=(title,...paragraphs)=>({title,paragraphs});
module.exports={
'core-keeper':{hook:'Căn cứ nhỏ sáng lên giữa một thế giới không thấy mặt trời',theme:'Tự do xây dựng',lede:'Một cái cuốc, chút gỗ và khoảng tối trước mặt: Core Keeper bắt đầu giản dị đến mức dễ bị xem như một game đào quặng nữa. Nhưng hãy nhìn căn cứ sau vài chuyến đi. Những chiếc rương bắt đầu có trật tự, luống cây có người chăm, đường hầm có đuốc. Thứ giữ chân người chơi không chỉ nằm ở con boss kế tiếp; nó nằm ở dấu vết mà cả nhóm để lại dưới lòng đất.',chapters:[section('Ngọn lõi không đưa cho bạn một danh sách việc cần làm','Bạn thức dậy trong một hang động, cạnh một di vật lớn mang tên Core. Bối cảnh ấy đủ tạo một câu hỏi nhưng không lập tức đẩy bạn vào chuỗi hội thoại. Core Keeper dành chỗ cho một dạng kể chuyện khác: đường ray dẫn về nhà, căn phòng dành cho một người bạn, vết tích của chuyến thám hiểm bị bỏ dở. Hành trình có mục tiêu tiến triển, nhưng đời sống ở giữa các mục tiêu mới khiến nơi này thuộc về bạn.','Cách mở đầu này hợp với nhóm thích tự phân công. Người đào quặng, người lo thức ăn và người xây tường không phải những vai trò cứng mà game ép chọn. Chúng nảy sinh từ việc mỗi người thấy một nhu cầu khác nhau. Khi cả nhóm trở về cùng một chỗ để cất đồ, vòng lặp tài nguyên có thêm ý nghĩa xã hội: căn cứ là thành quả chung, không chỉ là trạm sửa công cụ.'),section('Đào thêm một ô, mở thêm một khả năng','Một bức tường chắn đường là lời mời hành động rất rõ. Phá nó, nhặt tài nguyên, rồi nhìn thấy một vật liệu hoặc sinh vật chưa quen. Khoảnh khắc ấy nối việc thám hiểm với chế tạo: công cụ tốt hơn cho phép đi xa hơn, còn một khu vực mới lại thay đổi thứ bạn muốn mang về. Sự tiến bộ có thể đọc ngay trên bản đồ và trong cách căn cứ mở rộng.','Tuy nhiên, tự do cũng đi kèm những chuyến đi chỉ để bổ sung nguyên liệu. Nếu mọi chiếc rương trở thành một đống lộn xộn, game có thể biến thành việc tìm món đồ vừa cất. Đặt một quy ước lưu trữ sớm và để lại đường về dễ nhận biết giúp phần khám phá bớt bị ngắt bởi những công việc hoàn toàn có thể tránh.'),section('Boss là phép thử của cả căn cứ','Chiến đấu không đứng tách khỏi việc trồng trọt và chế tạo. Thức ăn, trang bị và không gian quanh cuộc chạm trán đều là những thứ có thể chuẩn bị từ trước. Vì vậy, một thất bại đáng xem lại không chỉ nằm ở thao tác né. Nó còn nằm ở câu hỏi nhóm đã mang gì, đường rút có đủ thoáng không và ai đang giữ những món đồ cần thiết.','Đây là khác biệt quan trọng so với việc xem boss như cánh cổng khóa tiến trình. Cuộc thám hiểm thành công thường bắt đầu từ những lựa chọn rất nhỏ ở nhà. Khi chuẩn bị và thực hiện nối với nhau, người ít thích phản xạ nhanh vẫn có thể góp phần đáng kể vào một chuyến đi khó.'),section('Bóng tối cần những điểm sáng','Cụm tinh thể và ngọn đuốc không đơn thuần làm đẹp một nền pixel. Chúng tạo mốc định hướng trong không gian dễ khiến người chơi mất cảm giác khoảng cách. Một căn phòng được thắp sáng có thể trở thành lời nhắc rằng bạn đã đến đây, đã sửa chỗ này và đang dần hiểu cấu trúc của hang động.','Nếu chơi một mình, nhịp game sẽ thiên về quản lý chuyến đi hơn sự huyên náo của co-op. Cả hai cách đều có lý do để tồn tại, nhưng nên chọn theo điều bạn muốn giữ lại: một công trình tỉ mỉ do mình xây hay những câu chuyện nhỏ cả nhóm tạo ra khi kế hoạch đào bới đi chệch hướng.')],verdict:'Core Keeper hấp dẫn khi tài nguyên không còn chỉ là con số, mà trở thành một nơi chốn. Hãy đến với nó nếu bạn thích xây một căn cứ có công dụng thực sự và để những cuộc thám hiểm thay đổi cách căn cứ ấy vận hành. Nếu cần một cốt truyện dẫn dắt liên tục, khoảng tự do này có thể quá rộng.',fit:'Thích chế tạo, thám hiểm và cùng bạn bè xây một nơi để quay về.',caution:'Có thu thập lặp lại; sắp xếp đồ và chuẩn bị chuyến đi chiếm nhiều thời gian.'},
'celeste':{hook:'Ngọn núi không biến mất chỉ vì Madeline đã sợ',theme:'Đối diện bản thân',lede:'Celeste không cần một bộ điều khiển phức tạp để làm bàn tay căng lên. Một cú nhảy, một lần lướt và bức tường vừa hụt là đủ. Điều đáng nói là game không dùng thất bại để đuổi người chơi ra ngoài. Nó trả Madeline về rất nhanh, giữ nguyên đích đến trong tầm mắt và hỏi: lần này bạn muốn thử khác đi ở đâu?',chapters:[section('Madeline mang theo nhiều hơn một chiếc ba lô','Chuyến leo núi là một hành trình cụ thể, nhưng những cuộc gặp và cuộc đối thoại khiến nó mang thêm sức nặng. Madeline không chỉ gặp chướng ngại vật; cô còn phải sống cùng nỗi lo và phần bản thân mà mình không muốn thừa nhận. Celeste không biến điều đó thành bài giảng dài. Nó đặt cảm xúc cạnh chuyển động, để một không gian khó vượt qua nói cùng câu chuyện.','Điểm mạnh nằm ở việc tránh xem sự can đảm như trạng thái đã đạt được một lần rồi giữ mãi. Có lúc Madeline muốn tiếp tục, có lúc cô hoài nghi. Những lần trở lại sau một cú ngã khiến chủ đề ấy hiện diện trong tay người chơi, thay vì chỉ xuất hiện trong một đoạn cắt cảnh cuối chương.'),section('Mỗi căn phòng là một câu hỏi vừa tầm mắt','Bạn thường nhìn thấy đích của một đoạn thử thách trước khi biết cách đến đó. Điều này làm thất bại có chỗ để giải thích: lướt quá sớm, bám tường quá lâu hoặc đặt hướng chưa chính xác. Game xây độ khó bằng cách kết hợp những động tác đã học, rồi đưa vào một yếu tố môi trường làm nhịp cũ phải thay đổi.','Thời gian trở lại ngắn giữ cho thử nghiệm có nhịp. Bạn không phải đi lại một đoạn đường dài chỉ để thử đúng cú nhảy vừa sai. Nhờ vậy, sự bực bội dễ được chuyển thành một kế hoạch cụ thể. Nhưng khi đã mệt, tốc độ thử lại nhanh cũng có thể kéo người chơi vào một vòng nhấn nút thiếu quan sát; nghỉ vài phút đôi khi hiệu quả hơn cố thêm hai mươi lần.'),section('Dâu tây không phải điều kiện để xứng đáng','Các vật phẩm và đường đi khó hơn tạo cơ hội cho người muốn đẩy kỹ năng xa hơn. Chúng không cần trở thành nghĩa vụ cho tất cả. Celeste làm rõ rằng hoàn thành một hành trình và làm chủ mọi thử thách phụ là hai mục tiêu khác nhau, và người chơi có thể chọn mức độ gắn bó phù hợp.','Assist Mode còn cho phép điều chỉnh trải nghiệm thay vì giữ một cánh cửa duy nhất. Điều ấy rất hợp với chủ đề của game: tiến bộ không nhất thiết phải giống tiến bộ của người bên cạnh. Khi viết về độ khó, nên xét cả cấu trúc hỗ trợ này chứ không chỉ đếm số lần chết.'),section('Âm nhạc giữ nhịp khi đôi tay mất nhịp','Màu sắc và âm nhạc của Celeste không chỉ xác định từng chương. Chúng giúp cảm nhận sự căng thẳng, khoảng nghỉ và chuyển biến của Madeline. Những đoạn nền giàu chuyển động làm hành trình sống động, trong khi các chướng ngại quan trọng vẫn có hình dáng đủ rõ để đọc trong một khoảnh khắc.','Có thể nhìn game như một platformer chính xác, hoặc một câu chuyện về việc chấp nhận mình. Hai cách đọc ấy không cạnh tranh nhau. Cái hay là những lần hụt, chờ và thử lại vừa vận hành như bài tập kỹ năng, vừa làm cho câu chuyện bớt xa lạ với người đang cầm tay điều khiển.')],verdict:'Celeste cho thất bại một kích thước vừa phải: đủ để học, đủ để thấy khó, nhưng không quá dài để nỗi sợ lấn hết sự tò mò. Giá trị của ngọn núi nằm ở cách Madeline đi cùng chính mình, và cách người chơi dần tìm được nhịp tay của riêng họ.',fit:'Muốn platformer chính xác cùng một câu chuyện giàu cảm xúc.',caution:'Đòi hỏi luyện tập; nội dung phụ khó hơn đáng kể, nên dùng hỗ trợ khi cần.'},
 'tunic':{hook:'Tờ hướng dẫn cũ có thể đổi nghĩa cả con đường vừa đi qua',theme:'Tri thức là chìa khóa',lede:'TUNIC trông như một món đồ chơi nhỏ đặt trên bàn: chú cáo, thanh kiếm, cỏ xanh và những khối đá tròn cạnh. Rồi một trang giấy xuất hiện. Nó có sơ đồ, hình vẽ, những dòng chữ khó đọc và dấu vết của một người đã dùng cuốn sách trước bạn. Từ đó, câu hỏi không còn chỉ là đi đâu, mà là mình đã bỏ sót điều gì ngay trước mắt.',chapters:[section('Chú cáo không được trao một lời giải thích đầy đủ','TUNIC cho người chơi bước vào thế giới với rất ít vốn hiểu biết. Sự thiếu hụt ấy có chủ đích: một ký hiệu chưa đọc được có thể là trang trí, lời nhắc hay một quy tắc quan trọng. Cảm giác xa lạ xuất hiện ngay trong việc hiểu giao diện và bản đồ, chứ không chỉ ở các di tích được dựng làm phông nền.','Thay vì một người hướng dẫn liên tục nói điều cần làm, cuốn sách nhỏ trở thành bạn đồng hành. Tìm được một trang mới có giá trị vì nó bổ sung một mảnh ngữ cảnh. Phần thưởng đôi khi không thay đổi sức mạnh của cáo, nhưng thay đổi cách bạn nhìn một lối đi đã gặp từ lâu.'),section('Trang giấy là một vật thể trong cuộc phiêu lưu','Hình minh họa, chú thích và cách bố trí trang tạo cảm giác đây là tài liệu có lịch sử, không phải một menu ngoài game. Người chơi có thể đối chiếu nó với thế giới đang đứng trong đó. Khi một nét vẽ và một hình dạng ngoài môi trường khớp nhau, sự hiểu biết xuất hiện từ hành động quan sát của chính bạn.','Vì vậy, xem một hướng dẫn đầy đủ từ đầu sẽ làm mất một phần lớn giá trị của TUNIC. Nếu mắc kẹt, nên tìm một gợi ý về khu vực hoặc một câu hỏi cần đặt ra, thay vì xem ngay câu trả lời. Bài phân tích này giữ lại các lời giải quan trọng để cuốn sách vẫn còn thứ để nói khi bạn tự mở nó.'),section('Dáng vẻ hiền lành, những trận đấu thì không hẳn','Né, đánh và quản lý sức bền đòi hỏi giữ khoảng cách có ý thức. Lao vào vì nhân vật trông đáng yêu không phải một chiến thuật đáng tin. Những cuộc chạm trán buộc bạn đọc phạm vi đòn đánh và tìm thời điểm an toàn, trong khi tài nguyên hạn chế khiến việc đi thêm một đoạn phải được cân nhắc.','Sự căng thẳng này giúp thế giới có độ nguy hiểm, nhưng cũng có thể cản người chỉ muốn theo đuổi câu đố. Các tùy chọn hỗ trợ chiến đấu là một cách hợp lý để giữ hành trình khám phá mở. TUNIC có nhiều lớp hấp dẫn; không cần phải yêu tất cả với cùng một mức độ.'),section('Góc máy đẳng cự cũng biết giấu chuyện','Một vật thể có thể che một lối đi. Một bức tường có thể khiến khoảng trống bị đọc nhầm thành ngõ cụt. TUNIC dùng hình học và góc nhìn để tạo những phát hiện nhỏ trước khi yêu cầu người chơi suy luận xa hơn. Bởi thế, đi chậm và thử vòng quanh cảnh vật thường có ích hơn chỉ nhìn vào mũi tên tưởng tượng.','Âm thanh và các không gian cổ xưa giữ lại vẻ bí ẩn sau lớp màu dịu. Khi diện mạo dễ thương bắt đầu nhường chỗ cho những câu hỏi khó giải thích, game tạo được một khoảng bất an vừa đủ. Vẻ đẹp ở đây không chỉ để ngắm: nó khiến điều bị che khuất càng đáng tìm.')],verdict:'TUNIC đáng nhớ nhất khi một kiến thức mới làm cả thế giới cũ thay đổi. Hãy giữ một chút kiên nhẫn với cuốn sách và một chút hoài nghi với những gì tưởng như chỉ là phong cảnh. Đó là nơi cuộc phiêu lưu riêng của game bắt đầu.',fit:'Thích tự giải mã, ghi chú và tìm những lối đi không được đánh dấu.',caution:'Chỉ dẫn mơ hồ và chiến đấu khó; tránh hướng dẫn có lời giải đầy đủ.'}
};
Object.assign(module.exports,{
'hollow-knight':{hook:'Hallownest kể chuyện bằng những thứ còn sót lại',theme:'Di tích và ký ức',lede:'Trước khi gặp một trận đấu lớn, Hollow Knight cho bạn nghe sự vắng lặng. Dirtmouth thưa người, đường hầm dẫn xuống sâu và tiếng nhạc của Cornifer có thể trở thành thứ âm thanh thân thiện nhất trong một khu vực chưa biết tên. Hallownest không chỉ là bản đồ cần mở; nó là một vương quốc mà mỗi ngõ rẽ đều mang dấu hiệu của điều đã mất.',chapters:[section('Một vương quốc không còn tự giải thích được mình','Hollow Knight để lịch sử nằm trong kiến trúc, sinh vật và những cuộc gặp ngắn. Một nhà ga bỏ hoang hay căn phòng còn dấu sinh hoạt khiến người chơi tự hỏi ai từng sống ở đó. Cách kể này không vội ghép mọi mảnh thành một lời giải, nhờ vậy sự tò mò có thể tồn tại ngay cả khi bạn chưa hiểu những tên gọi trong hội thoại.','Cần phân biệt bí ẩn với việc không có chuyện gì để kể. Hallownest liên tục để lại bằng chứng của một đời sống trước đây. Người chơi càng đi xa càng có nhiều cách đọc lại những nơi cũ. Điều quan trọng là giữ các phát hiện lớn nguyên vẹn, thay vì biến review thành một bản tóm tắt toàn bộ lịch sử của vương quốc.'),section('Bản đồ phải được học, không chỉ được mở','Tìm Cornifer, mua bản đồ và ngồi nghỉ để cập nhật hành trình tạo một nhịp khám phá riêng. Bạn không luôn có thông tin đầy đủ ngay khi bước vào phòng mới. Một lối tắt vừa mở vì thế có giá trị rất cụ thể: nó rút ngắn đường trở về và giúp hình dung cách khu vực này nối với phần còn lại.','Nhưng đây cũng là chỗ game dễ làm người mới thấy lạc. Sau một lần thua, chuyến quay lại có thể dài hơn điều họ mong muốn. Đừng xem mọi ngõ cụt như một lỗi định hướng của mình; nhiều đường được thiết kế để chờ một khả năng di chuyển khác. Nhận ra sự khác biệt giữa chưa hiểu đường và chưa có công cụ là kỹ năng quan trọng của chuyến đi.'),section('Một lần hồi máu cũng là một quyết định chiến đấu','Đánh trúng để tích Soul rồi chọn dùng phép hay hồi phục khiến tấn công và phòng thủ gắn với nhau. Hồi máu cần một khoảng trống đủ lâu; vì vậy việc đọc đòn của đối thủ không chỉ giúp né mà còn xác định lúc nào có thể lấy lại thế trận. Tầm kiếm và sức đẩy sau va chạm làm vị trí đứng trở nên quan trọng.','Charms cho phép thay đổi ưu tiên mà không xóa nền tảng ấy. Bạn có thể muốn tầm đánh, hiệu quả phép hoặc sự an toàn, nhưng vẫn phải hiểu nhịp đối thủ. Khi một boss trở nên dễ đọc hơn sau vài lần thử, phần thưởng không chỉ là vượt qua một cánh cửa mà là cảm giác đã thực sự học được một ngôn ngữ chuyển động.'),section('Mưa ở City of Tears không chỉ là phông nền','Hình vẽ tay khiến sinh vật có vẻ vừa đáng yêu vừa xa lạ. Các lớp cảnh và âm nhạc tạo không gian rộng hơn kích thước của khung hình. Những khoảng im lặng giữa các trận đánh khiến một khu vực mới có thời gian hiện ra như nơi chốn, thay vì chỉ là chuỗi chướng ngại.','Hollow Knight sẽ không hợp với người muốn chỉ dẫn liên tục hoặc hồi phục tiến trình ngay tại cửa boss. Nó cần sự kiên nhẫn với việc đi lại và một chút thích thú trong chuyện lạc đường. Nếu chấp nhận nhịp đó, Hallownest có thể ở lại trong trí nhớ bằng một ga tàu hoặc một bản nhạc, không chỉ bằng danh sách những đối thủ đã hạ.')],verdict:'Sức hút của Hollow Knight nằm trong mối nối giữa bàn tay đang học đánh và đôi mắt đang học đọc một vương quốc. Thế giới ấy đôi khi khắc nghiệt và ít chỉ đường, nhưng những lối tắt do chính bạn tìm thấy có giá trị vì bạn đã biết cảm giác thiếu chúng.',fit:'Thích metroidvania, môi trường kể chuyện và chiến đấu cần luyện tập.',caution:'Đi lại sau thất bại và bản đồ chưa đầy đủ có thể gây nản.'},
'sea-of-stars':{hook:'Ánh trăng, mặt trời và nhịp bấm trong một cuộc phiêu lưu theo lượt',theme:'Tình bạn và hành trình',lede:'Một cảnh nước lấp lánh đủ khiến Sea of Stars gợi nhớ những chuyến phiêu lưu pixel ngày trước. Nhưng vẻ hoài cổ chỉ là lời chào. Bên dưới nó là những lượt đánh cần canh nhịp, những kỹ năng phải phối hợp và một thế giới liên tục tìm cách đưa nhóm bạn sang một khung cảnh mới.',chapters:[section('Hai chiến binh Chí tuyến, một thế giới lớn hơn lời tiên tri','Zale và Valere mang sức mạnh gắn với mặt trời và mặt trăng. Câu chuyện đưa họ lên đường đối mặt với mối đe dọa của Fleshmancer, nhưng hành trình không chỉ dựa vào sứ mệnh được giao. Những người đi cùng, cuộc sống trong các thị trấn và các khoảng nghỉ giúp cuộc phiêu lưu có chất gần gũi giữa một bối cảnh kỳ ảo.','Cách kể hướng đến cảm giác một nhóm bạn đang cùng đi xa. Đó là lựa chọn dễ tiếp cận, nhưng người mong những nhân vật chính có góc cạnh tâm lý thật mạnh có thể thấy phần mở đầu còn hiền. Game phát triển sức hấp dẫn bằng nhịp gặp gỡ và khám phá nhiều hơn bằng việc giữ bí mật về động cơ của mọi nhân vật.'),section('Lượt của bạn chưa kết thúc ở thao tác chọn đòn','Canh thời điểm khi tấn công và đỡ đòn giúp người chơi tham gia vào mỗi lượt. Hệ thống khóa trước đòn đặc biệt của đối phương còn yêu cầu nhìn loại sát thương cần thiết rồi chọn trình tự xử lý. Một lượt đánh vì vậy có thể phục vụ nhiều mục đích: gây sát thương, lấy năng lượng hoặc phá ý định nguy hiểm.','Điều hay là chiến thuật và phản xạ có thể hỗ trợ nhau, thay vì một bên thay thế hoàn toàn bên kia. Tuy nhiên, lặp lại cùng một thao tác canh nhịp qua nhiều trận có thể làm một số người mệt. Nên cân nhắc điều ấy nếu bạn thích RPG theo lượt vì nó cho phép đặt tay xuống và suy nghĩ mà không cần chú ý một thời điểm bấm.'),section('Đi qua thế giới bằng nhiều động tác nhỏ','Leo trèo, bơi và di chuyển qua địa hình giúp các khu vực có cảm giác liên tục, không chỉ là màn hình nối nhau bằng cửa. Những câu đố môi trường thường đưa ra một việc vừa tầm để làm giữa các trận đấu. Chúng giữ hành trình có nhịp thay đổi, đồng thời cho người chơi thời gian ngắm cảnh.','Các hoạt động như câu cá và trò chơi bàn là những nhánh rẽ để đổi nhịp, không cần thành mục tiêu hoàn thành tuyệt đối. Sea of Stars hợp với cách chơi cho phép mình dừng trước một thị trấn hoặc quay lại một góc chưa xem kỹ. Chạy thẳng theo mục tiêu có thể làm mất phần duyên nằm giữa các biến cố lớn.'),section('Pixel art được dựng bằng ánh sáng, không chỉ bằng điểm ảnh','Ánh sáng trên nước, thay đổi bảng màu và độ sâu của cảnh làm các môi trường có chất sống động. Một cảnh đêm khác cảnh ngày không chỉ vì dùng tông tối hơn; cảm giác về độ ấm, khoảng cách và nơi cần nhìn cũng thay đổi. Đây là nơi mỹ thuật trực tiếp nâng cảm giác du hành.','Âm nhạc giữ tinh thần phiêu lưu rõ ràng, nhưng hình ảnh đẹp không tự giải quyết được mọi hạn chế của kịch bản hay sự lặp trong chiến đấu. Sea of Stars đáng đọc như một cuộc phiêu lưu được chăm chút về nhịp và diện mạo. Đừng đặt lên nó nghĩa vụ phải tái hiện toàn bộ cảm xúc bạn từng có với một RPG thời thơ ấu.')],verdict:'Sea of Stars mạnh ở cảm giác đi cùng một nhóm bạn qua những nơi đẹp, cùng hệ thống theo lượt vẫn cần đôi tay tham gia. Vẻ hoài cổ mở cửa, còn việc bạn có ở lại lâu hay không phụ thuộc vào mức độ thích nhịp phiêu lưu và các thao tác canh thời điểm của nó.',fit:'Muốn RPG theo lượt dễ tiếp cận, cảnh pixel giàu ánh sáng và một nhóm bạn đồng hành.',caution:'Nhân vật chính có thể thiếu góc cạnh; canh nhịp lặp lại không hợp mọi người.'},
'outer-wilds':{hook:'Chiếc tàu nhỏ, hai mươi hai phút và một hệ mặt trời đầy câu hỏi',theme:'Tò mò và hữu hạn',lede:'Outer Wilds cho bạn rời bệ phóng trước khi đưa ra một danh sách việc phải làm. Có thể bay tới hành tinh đang thấy, tìm tiếng nhạc ngoài xa hoặc thử hiểu một dấu vết của người Nomai. Sau đó, thời gian làm mọi thứ đổi khác. Chuyến đi tiếp theo không bắt đầu bằng trang bị mạnh hơn; nó bắt đầu bằng câu hỏi tốt hơn.',chapters:[section('Nhà thám hiểm không nhận một cuộc săn kho báu','Bạn là một người Hearthian bước vào chương trình khám phá không gian, với một con tàu và những công cụ giản dị. Bối cảnh khuyến khích tò mò thay vì ra lệnh. Những dấu vết Nomai tạo một mạng lưới câu hỏi: một địa điểm nhắc tới nơi khác, một ghi chép khiến điều vừa thấy trở nên đáng ngờ.','Câu chuyện phát triển từ việc nối các mảnh ấy. Vì vậy, đọc trước lời giải không giống được trợ giúp vượt một đoạn chiến đấu; nó có thể lấy đi chính cảm giác tiến bộ của game. Bài này chỉ bàn cấu trúc trải nghiệm và tiền đề công khai, giữ những phát hiện quyết định cho hành trình của bạn.'),section('Một vòng lặp không giữ nguyên thế giới','Trong giới hạn thời gian của mỗi vòng, môi trường tiếp tục biến đổi. Một nơi có thể dễ tới ở thời điểm này nhưng trở nên khác ở thời điểm khác. Bạn học không chỉ tọa độ mà cả nhịp của hệ mặt trời, rồi lên kế hoạch chuyến đi theo hiểu biết mới.','Điều này làm chuyến bay thất bại vẫn có giá trị nếu nó cho bạn một thông tin. Nhưng khi đã biết điều cần làm mà thao tác điều khiển chưa theo kịp, việc lặp lại có thể gây bực. Outer Wilds không xóa hoàn toàn khoảng cách giữa hiểu và thực hiện; học cách tiếp cận chậm, dùng công cụ hỗ trợ bay và chuẩn bị đường đi vẫn quan trọng.'),section('Nhật ký tàu là bản đồ của những điều chưa hiểu','Các mối nối trong nhật ký giúp bạn nhìn cuộc điều tra như một cấu trúc thay vì một đống ghi chép. Một nút còn thông tin để khám phá là lời mời quay lại, không nhất thiết là bằng chứng bạn phải đi tới đó ngay. Game để nhiều hướng tò mò tồn tại song song.','Nhờ vậy, khi một câu hỏi bế tắc, chuyển sang hành tinh khác có thể là bước đi tốt. Một mảnh ngữ cảnh ở xa đôi khi làm điều đang mắc kẹt trở nên rõ hơn. Cảm giác khám phá đến từ sự nối kết đó, chứ không chỉ từ việc nhìn thấy một cảnh lạ lần đầu.'),section('Âm nhạc khiến khoảng không bớt xa lạ','Những nhạc cụ của các nhà thám hiểm tạo một sợi dây giữa các thiên thể. Dù ở một nơi nguy hiểm, một tín hiệu quen vẫn nhắc rằng có người khác trong hành trình. Ngọn lửa trại và con tàu nhỏ khiến quy mô vũ trụ được đặt cạnh những thứ rất gần gũi.','Outer Wilds có thể tạo cảm giác bất an vì không gian, nước sâu hoặc sự hữu hạn của thời gian. Hãy xét những điều ấy trước khi bắt đầu, nhưng không cần biến chúng thành lý do phủ nhận vẻ dịu dàng của game. Sự tò mò và nỗi sợ cùng tồn tại, và chính sự cùng tồn tại đó làm một bước đi tiếp theo trở nên đáng nhớ.')],verdict:'Outer Wilds biến hiểu biết thành tiến trình và thời gian thành một phần của địa hình. Nó cần người chơi chịu đặt câu hỏi, đổi hướng và chấp nhận chưa hiểu ngay. Đổi lại, một phát hiện do mình nối được có thể mang sức nặng mà không thanh kinh nghiệm nào diễn tả hết.',fit:'Thích điều tra phi tuyến, thiên văn giả tưởng và tự nối manh mối.',caution:'Dễ bị spoiler; điều khiển tàu và một số môi trường có thể gây khó chịu.'}
});
Object.assign(module.exports,{
'stardew-valley':{hook:'Một mùa vụ tốt chưa chắc là mùa kiếm nhiều tiền nhất',theme:'Đời sống và cộng đồng',lede:'Chiếc lịch trong Stardew Valley có thể khiến bạn tính từng ngày, nhưng thung lũng không chỉ tồn tại để được tối ưu. Có một người đang đợi ở quảng trường, một lễ hội vào cuối tuần và căn nhà chưa có món đồ bạn muốn đặt cạnh cửa. Điều thú vị là game đủ sâu để lập kế hoạch rất nghiêm túc, nhưng vẫn để một buổi câu cá trở thành lý do hợp lệ để bỏ kế hoạch ấy.',chapters:[section('Rời chiếc bàn làm việc, nhận một mảnh đất chưa thành hình','Bạn thừa hưởng trang trại của ông và bắt đầu lại ở một nơi nhỏ hơn. Tiền đề ấy đặt lao động vào một ngữ cảnh dễ hiểu: đây là cơ hội tạo nhịp sống do mình chọn. Dọn cỏ và tưới cây ban đầu không lãng mạn, nhưng mỗi thay đổi để lại trên đất đều nhìn thấy được. Sự tiến bộ vì thế có tính cá nhân hơn một hàng số thống kê.','Thung lũng cũng có một xung đột về cách cộng đồng vận hành, thể hiện qua trung tâm sinh hoạt và Joja. Người chơi không chỉ chăm một mảnh đất tách biệt. Những việc mang tài nguyên ra khỏi trang trại có thể làm môi trường chung đổi khác, khiến sản xuất và đời sống thị trấn liên hệ với nhau.'),section('Thời gian ngắn tạo những ưu tiên dài','Năng lượng và đồng hồ ngày làm việc buộc bạn chọn thứ làm trước. Tưới cây, xuống mỏ hay đi tìm một người dân đều có giá cơ hội. Khi công cụ và hệ thống tự động hóa phát triển, phần thời gian được giải phóng mới thật sự cho thấy tác dụng của một nâng cấp. Nó trả lại quyền lựa chọn, không chỉ tăng sản lượng.','Mặt trái là người chơi dễ tự đặt áp lực phải làm hết. Một sinh nhật quên, một chuyến câu cá ít lợi nhuận không có nghĩa cả mùa đã hỏng. Stardew Valley có thể vận hành như bài toán hiệu suất, nhưng dùng mọi công cụ của bài toán ấy không phải cách duy nhất để tận hưởng game.'),section('Dân làng có lịch riêng, không chỉ có thanh thiện cảm','Việc nhớ nơi một người thường xuất hiện khiến gặp gỡ có chất đời thường. Những mẩu chuyện mở dần qua quan hệ tạo ngữ cảnh cho các món quà và cuộc trò chuyện. Bạn có thể bắt đầu từ một thói quen thuận tiện rồi nhận ra một nhân vật có vấn đề và mong muốn không giống ấn tượng đầu.','Tuy vậy, các hệ thống quan hệ vẫn có quy tắc có thể tra và tối ưu. Nếu biến mọi cuộc gặp thành nhiệm vụ tăng điểm, bạn có thể đánh mất phần bất ngờ. Để một vài thói quen tự hình thành thường tạo cảm giác sống trong thị trấn tốt hơn theo sát một bảng hướng dẫn.'),section('Cùng một con đường, bốn mùa khác nhau','Mùa thay đổi cây trồng, âm nhạc và diện mạo của những chỗ quen. Điều ấy khiến bản đồ có nhịp trở lại: nơi vừa đi qua vẫn đáng nhìn thêm khi bảng màu chuyển. Pixel art dễ đọc giúp công việc nhiều loại cùng tồn tại mà không cần một giao diện phô trương.','Co-op làm trang trại thành câu chuyện chung, nhưng cũng cần trao đổi về quỹ tiền và việc muốn làm. Với người chơi một mình, khoảng yên tĩnh có thể là thế mạnh. Chọn cách chơi theo nhịp sống bạn muốn tạo, thay vì cảm giác phải tận dụng mọi tính năng trong danh mục.')],verdict:'Stardew Valley giữ người chơi bằng những thứ dần trở nên quen: đường ra chợ, tiếng nhạc một mùa và một góc trang trại mình tự sắp. Nó cho phép tham vọng, nhưng cũng đủ rộng để ngày hôm nay chỉ cần dễ chịu.',fit:'Thích trồng trọt, quan hệ dân làng và một thế giới phát triển qua nhiều mùa.',caution:'Có việc lặp hằng ngày; xu hướng tối ưu hóa có thể tạo áp lực do chính người chơi đặt ra.'},
'a-short-hike':{hook:'Đỉnh núi là cái cớ để Claire đi một vòng',theme:'Những cuộc gặp nhỏ',lede:'Claire cần tìm sóng điện thoại trên cao, một lý do rất đời thường để bắt đầu chuyến leo núi. A Short Hike có thể đưa cô tới đích khá nhanh, nhưng liên tục đặt những điều đáng chú ý ở hai bên đường: người đang vẽ, một trò chơi trên bãi biển, một mỏm đá có thể thử bay xuống. Bạn đi xa hơn vì muốn, không phải vì nhiệm vụ chưa đánh dấu đủ ô.',chapters:[section('Một cuộc gọi làm đích đến có sức nặng vừa đủ','Câu chuyện không cần biến chuyến đi thành việc cứu cả hòn đảo. Mục tiêu cá nhân của Claire tạo một hướng để theo, còn những nhân vật gặp giữa đường làm thời gian chờ cuộc gọi bớt trống. Họ thường có một việc nhỏ đang làm và một giọng nói dễ nhận ra qua hội thoại ngắn.','Cách viết duyên nằm ở sự tiết chế. Game không ép mỗi người phải có một bí mật lớn để đáng quan tâm. Một cuộc trò chuyện vài câu vẫn có thể khiến một bãi biển khác đi, bởi từ đó nơi ấy gắn với một người bạn nhớ.'),section('Lông vàng biến giới hạn thành lời mời','Khả năng leo và bay của Claire mở rộng theo những chiếc lông kiếm được. Chỗ trước đó phải đi vòng dần trở thành chỗ có thể thử leo thẳng. Nhưng nâng cấp không chỉ phục vụ đường lên đỉnh: nó làm việc di chuyển trên cả hòn đảo có thêm sự vui nhộn.','Những giới hạn ban đầu giúp người chơi chú ý địa hình. Khi đã bay xa hơn, quay lại một nơi quen có thể tạo một góc nhìn mới. Đây là dạng tiến bộ nhẹ nhàng: bạn nhận ra mình đang dùng không gian thoải mái hơn, thay vì chỉ thấy một con số sức mạnh tăng lên.'),section('Hoạt động phụ không phải món nợ','Câu cá, đua và các cuộc gặp cho phép đổi nhịp trong một chuyến đi ngắn. Chúng không cần được hoàn tất theo một thứ tự cố định để câu chuyện có ý nghĩa. A Short Hike tin rằng điều nhỏ cũng đủ hấp dẫn nếu hành động di chuyển vốn đã dễ chịu.','Người mong những hệ thống sâu hoặc nhiều giờ thử thách sẽ thấy quy mô này khiêm tốn. Nhưng kéo dài mọi hoạt động có thể làm mất sự gọn ghẽ đang giữ game tự nhiên. Đây là một buổi đi chơi được chăm chút, không phải một danh sách nhiệm vụ được cố tình làm dài.'),section('Một tấm bưu thiếp biết chuyển động','Góc nhìn, màu sắc và độ thô có chủ đích của hình ảnh khiến hòn đảo giống một ký ức nhỏ. Các nhân vật có đủ chuyển động và nét riêng để gần gũi mà không cần chi tiết dày đặc. Âm nhạc nâng khoảng yên bình nhưng vẫn để môi trường có chỗ lên tiếng.','Thử đi chậm ở lần đầu, rồi bay xuống một con đường khác sau khi lên cao. A Short Hike mạnh ở việc biến hành trình trở về thành niềm vui. Bạn không chỉ đã chạm đích; bạn đã hiểu hòn đảo bằng nhiều đường khác nhau.')],verdict:'A Short Hike làm một việc nhỏ rất trọn: cho người chơi một lý do để đi, rồi đủ khoảng tự do để tự chọn điều muốn nhớ. Sự ngắn gọn là phần cấu trúc của chuyến đi, không phải một lời hứa về game kéo dài vô tận.',fit:'Muốn một chuyến khám phá nhẹ, hội thoại duyên và chuyển động bay lượn.',caution:'Ngắn, ít thử thách sâu; hợp một buổi thư giãn hơn một dự án chơi dài.'},
'hades':{hook:'Trở về nhà cũng là một phần của cuộc vượt ngục',theme:'Gia đình và thất bại',lede:'Zagreus lao ra khỏi nhà với một vũ khí và sự bướng bỉnh. Căn phòng tiếp theo có thể cho anh một ân huệ, một cuộc đấu hoặc lý do để quay lại rất sớm. Hades khiến chuyện trở về không chỉ là màn hình thất bại: người ở nhà vẫn có điều để nói, và cuộc vượt ngục vừa rồi trở thành một phần của quan hệ với họ.',chapters:[section('Gia đình không đứng ngoài vòng lặp roguelike','Khát vọng rời địa ngục đặt Zagreus vào xung đột với Hades, nhưng câu chuyện được kể qua nhiều lần xuất phát và trở về. Những người gặp trong nhà và trên đường có thái độ, mục đích và mối liên hệ riêng. Hội thoại phản ứng với hành trình giúp thất bại có chỗ trong thế giới, thay vì bị coi như chuyện xảy ra ngoài kịch bản.','Điều ấy không làm mỗi cái chết trở nên vui. Nó làm việc quay lại có một phần thưởng khác với vật phẩm. Khi đang mắc ở một đối thủ, người chơi vẫn có thể tiến trong một mối quan hệ hoặc hiểu một động cơ rõ hơn. Câu chuyện và kỹ năng cùng phát triển, nhưng không cần phát triển cùng tốc độ.'),section('Một ân huệ có thể làm vũ khí đổi tính','Vũ khí xác định nền tảng, còn ân huệ bổ sung những điều kiện và hiệu ứng làm một lượt chạy có hướng riêng. Chọn phần thưởng vì nó hợp với cách đánh đang có khác với chọn chỉ vì mức hiếm. Hades khuyến khích nhìn tương tác giữa các yếu tố, rồi thử xây một lối chơi có mục đích.','Các quyết định diễn ra nhanh nhưng không hời hợt. Một lựa chọn đổi tầm hiệu quả của đòn đánh có thể kéo theo cách né, vị trí đứng và thứ cần tìm ở cửa hàng. Khi một kết hợp vận hành tốt, niềm vui đến từ việc nhận ra chính mình đã tạo ra nhịp chiến đấu ấy.'),section('Căn phòng đông, thông tin vẫn cần đọc được','Đòn của đối thủ, bẫy và vùng hiệu ứng buộc người chơi giữ mắt trên không gian. Di chuyển liên tục có ích, nhưng né không có kế hoạch có thể đưa Zagreus vào vùng nguy hiểm tiếp theo. Thành công dần đến từ việc hiểu căn phòng, không chỉ từ việc tăng sát thương.','Tốc độ và hiệu ứng cũng là một giới hạn tiếp cận. God Mode hỗ trợ người muốn theo câu chuyện mà chưa có phản xạ đủ vững. Dùng nó không làm mất việc chọn ân huệ hay học đường đi; nó điều chỉnh áp lực để những lớp khác của game vẫn có thể phát huy.'),section('Nhà Hades có người, giọng nói và những việc chưa xong','Chân dung và diễn xuất giọng nói giúp dàn nhân vật hiện diện rõ sau những trận đánh ngắn. Âm nhạc giữ năng lượng của cuộc vượt ngục, rồi nhường không gian cho chuyện trò khi trở về. Vẻ đẹp không chỉ nằm trong từng hình vẽ, mà trong sự đối lập giữa chuyển động dồn dập và những người đang đợi.','Các khu vực vẫn lặp lại nhiều lần. Nếu điều bạn muốn là cảnh mới liên tục, hội thoại và cách xây dựng lượt chạy có thể không đủ bù. Hades hấp dẫn vì tạo nhiều nghĩa cho cùng một đường đi; nó không hứa đường đi ấy sẽ biến mất sau khi bạn đã thuộc.')],verdict:'Hades nối lý do phải thử lại với lý do muốn trở về. Chiến đấu có nhịp nhanh và nhiều lựa chọn, còn câu chuyện dành chỗ cho một hành trình không đi thẳng. Đó là sự ăn khớp khiến vòng lặp bớt lạnh lùng.',fit:'Thích roguelike hành động và nhân vật có quan hệ phát triển qua nhiều lượt.',caution:'Phải đi lại các vùng; hiệu ứng và tốc độ có thể gây quá tải.'},
'dead-cells':{hook:'Đừng yêu một thanh kiếm đến mức quên đọc căn phòng',theme:'Phản xạ và thích ứng',lede:'Dead Cells hấp dẫn ngay trong vài bước chạy: nhảy gọn, né nhanh, một vũ khí chạm mục tiêu tạo phản hồi rất rõ. Nhưng sự trơn tru ấy không bảo đảm sống sót. Một món đồ vừa nhặt có thể buộc bạn đổi khoảng cách đánh, còn một căn phòng hẹp có thể làm chiến thuật đang hiệu quả trở nên nguy hiểm.',chapters:[section('Cơ thể mới, hòn đảo vẫn còn những dấu vết','Người tù và thế giới dịch bệnh tạo bối cảnh cho những lần thử. Dead Cells không dành phần lớn thời lượng để kể một đường dây hội thoại liên tục. Những mẩu ghi chép, căn phòng và cuộc gặp đặt lịch sử vào giữa việc di chuyển, để người tò mò có thể dừng mà người thích hành động vẫn giữ được nhịp.','Cốt truyện ở đây là một lớp khám phá, không phải động lực duy nhất để chạy tiếp. Nếu cần gắn bó với nhân vật qua nhiều cảnh đối thoại, nên hiểu cấu trúc này từ đầu. Game đặt nhiều sức nặng hơn vào chuyện bàn tay học một khu vực và chọn cách vượt qua nó.'),section('Vũ khí là nhịp điệu, không chỉ là chỉ số','Cung, bẫy và những đòn cận chiến có thời điểm an toàn khác nhau. Đổi món đồ có nghĩa đổi cách đọc khoảng trống trước mặt. Một vũ khí chậm nhưng mạnh cần cơ hội rõ ràng; thứ nhanh hơn có thể phù hợp với việc gây áp lực rồi rút. Hiệu ứng hỗ trợ khiến các món đồ có thể phối hợp thành một kế hoạch.','Vì phần thưởng thay đổi, học một cách thích ứng quan trọng hơn chờ đúng món yêu thích. Nhưng chọn mọi thứ chỉ vì số sát thương cũng dễ làm lối chơi mất nhất quán. Niềm vui của một lượt chạy tốt thường nằm ở việc hiểu vì sao bộ trang bị này hợp nhau.'),section('Tốc độ phải đi cùng việc biết lúc nào dừng','Game khuyến khích chuyển động và phản ứng nhanh, nhưng không phải mọi cửa đều nên lao qua. Đọc dấu hiệu tấn công giúp bạn giữ sức cho những khu vực sau. Những hệ thống mở khóa dài hạn tạo lý do tiếp tục thử, còn việc vượt qua một đoạn khó bằng hiểu biết mới tạo phần thưởng ngay trong lượt chơi.','Mất một lượt dài vẫn có thể rất hụt hẫng. Các tùy chọn hỗ trợ và chỉnh trải nghiệm giúp giảm khoảng cách với người chưa quen, nhưng không thay đổi bản chất nhiều lần thử. Dead Cells phù hợp khi bạn thấy học lại một tình huống vẫn có điều đáng làm.'),section('Hoạt ảnh phục vụ cả vẻ đẹp lẫn phản xạ','Chuyển động làm đòn đánh có cá tính, trong khi bảng màu giúp từng khu vực khác nhau ngay khi bước vào. Phản hồi hình ảnh và âm thanh tạo cảm giác tác động rõ, khiến một chuỗi né và phản công thành công có sức hút riêng.','Ở nhịp nhanh, màn hình có thể nhiều thông tin. Người chơi cần học thứ nào báo nguy hiểm và thứ nào chỉ là hiệu ứng. Dead Cells có vẻ dễ lao vào vì điều khiển trơn, nhưng chiều sâu của nó xuất hiện khi bạn bắt đầu phân biệt những tín hiệu ấy trong thời gian rất ngắn.')],verdict:'Dead Cells mạnh ở cảm giác thích ứng bằng đôi tay: vũ khí thay đổi, phòng thay đổi và quyết định phải theo kịp. Nếu việc luyện một chuỗi thao tác là niềm vui của bạn, game có nhiều đất để đào sâu. Nếu cần tiến trình không bị gián đoạn, cái giá của thất bại đáng cân nhắc.',fit:'Thích hành động nhanh, nhiều vũ khí và học từ từng lượt chạy.',caution:'Một lượt dài có thể mất; cần đọc nhiều tín hiệu trong thời gian ngắn.'},
'dredge':{hook:'Chuyến cá cuối cùng luôn nghe như một ý tưởng hợp lý',theme:'Lòng tham và bất an',lede:'Bạn biết trời sắp tối. Khoang tàu vẫn còn một khoảng vừa cho thêm một con cá. Cảng cũng chưa quá xa. DREDGE tạo căng thẳng bằng chuỗi lý do nhỏ khiến người chơi tự thuyết phục mình ở lại thêm một chút, rồi làm mặt biển quen thuộc trở nên khó đọc khi ánh sáng đổi màu.',chapters:[section('Người đánh cá mới đến một nơi có nhiều chuyện chưa nói','Một công việc tưởng bình thường đưa bạn vào quần đảo với các cư dân, yêu cầu và vật thể kỳ lạ. Câu chuyện không cần bắt đầu bằng một con quái vật lớn. Nó để những dấu hiệu bất thường xuất hiện cạnh giao dịch và công việc hằng ngày, khiến sự nghi ngờ có thời gian tích lại.','Việc tìm hiểu diễn ra qua các chuyến đi và những món được kéo lên từ nước. Biển không chỉ là khoảng cách giữa hai điểm trên bản đồ; nó là nơi chuyện xảy ra. Điều này làm một nhiệm vụ kiếm tài nguyên cũng có thể trở thành bước vào sâu hơn trong bí mật của quần đảo.'),section('Khoang tàu là câu đố khiến lòng tham có hình dạng','Cá và trang bị chiếm những hình dạng khác nhau. Sắp xếp chúng khiến quyết định mang gì trở nên trực quan: một món lớn có thể tốt về giá nhưng cản những thứ cần thiết khác. Nâng cấp tàu mở khả năng mới, song không xóa việc phải chọn.','Vòng lặp kiếm tiền vì thế có nhiều bước hơn chỉ đưa số lên cao. Bạn lựa vùng đánh cá, nghĩ tới dụng cụ phù hợp và xem thời gian còn lại. Khi một chuyến đi trở về gọn gàng, cảm giác hài lòng đến từ việc đã tính vừa một hành trình, không chỉ từ tổng tiền bán được.'),section('Bóng tối thay đổi cách đọc cùng một vùng nước','Thời gian trôi khi bạn hành động trên biển. Căng thẳng xuất hiện vì mục tiêu kinh tế và sự an toàn không luôn đi cùng nhau. Các dấu hiệu bất thường, mức hoảng loạn và tầm nhìn làm quyết định quay về có thêm sức nặng, đặc biệt khi một nhiệm vụ đang gần hoàn tất.','DREDGE thường xây nỗi lo từ sự chờ đợi hơn một chuỗi giật mình liên tục. Người muốn kinh dị dữ dội có thể thấy nó nhẹ, trong khi người không thích mất kiểm soát ban đêm vẫn có thể thấy căng. Hiểu kiểu áp lực này giúp chọn game chính xác hơn chỉ nhìn nhãn kinh dị.'),section('Một con thuyền nhỏ đủ để biển trở nên rộng','Hình khối tiết chế và ánh sáng làm ban ngày có vẻ yên ổn. Khi âm thanh và màu trời đổi, cùng mặt nước ấy mang một sắc thái khác. Không cần mô tả mọi thứ thật chi tiết, game vẫn tạo khoảng để người chơi tưởng tượng về những gì nằm dưới đó.','Các công việc có thể lặp sau khi đã quen vùng đánh cá. Nếu chỉ chạy theo nâng cấp mà bỏ qua sự đổi nhịp và những lời nhắn từ cư dân, phần bí ẩn sẽ yếu đi. DREDGE hiệu quả khi bạn để công việc bình thường và nỗi bất an cùng tồn tại trên một chuyến tàu.')],verdict:'DREDGE biến việc quản lý một chuyến đánh cá thành cách đo mức liều lĩnh của người chơi. Cái đáng nhớ không chỉ là thứ ở dưới biển, mà là khoảnh khắc bạn tự quyết định bỏ qua một dấu hiệu rõ ràng để kiếm thêm chút lợi.',fit:'Thích quản lý nhẹ, khám phá trên biển và kinh dị dựa vào không khí.',caution:'Công việc đánh cá lặp lại; mức kinh dị tiết chế hơn vẻ bí ẩn của tiền đề.'},
'cocoon':{hook:'Đặt một thế giới xuống, bước vào một thế giới khác',theme:'Tư duy lồng nhau',lede:'COCOON bắt đầu với một động tác rất đơn giản: mang một quả cầu. Rồi quả cầu mở ra thành nơi chốn, nơi chốn lại có một quy tắc, và quy tắc ấy trở thành thứ cần mang sang chỗ khác. Game không làm bạn thông minh bằng một đoạn giải thích; nó sắp xếp tình huống để chính bạn nhận ra mình vừa hiểu thêm một lớp.',chapters:[section('Sinh vật nhỏ không cần một trang tiểu sử để bắt đầu','COCOON kể bằng môi trường và hành động. Hình dạng hữu cơ xen máy móc tạo cảm giác bạn đang ở trong một hệ thống có lịch sử nhưng không có người thuyết minh. Mục đích của nhân vật được đọc qua việc di chuyển và phản ứng của thế giới hơn qua lời thoại.','Sự im lặng này dành khoảng chú ý cho suy luận. Nó cũng có nghĩa người tìm một câu chuyện nhiều nhân vật và đối thoại có thể không thấy điều mình muốn. COCOON mạnh ở cách dẫn trí tò mò qua cấu trúc không gian, chứ không hứa một kịch bản giải thích hết những điều nhìn thấy.'),section('Quả cầu vừa là vật dụng vừa là địa điểm','Một quả cầu có thể được đặt vào cơ chế ở bên ngoài, đồng thời chứa một môi trường bạn đi vào. Tư duy phải thay đổi giữa hai cách xem cùng một vật: thứ có thể mang và nơi có thể sống trong đó. Khi thêm quy luật, game không bỏ cách hiểu cũ mà yêu cầu nối các lớp.','Niềm vui xuất hiện lúc nhận ra một khả năng đã học vẫn dùng được, nhưng ở một quan hệ mới. Bài này tránh đưa ví dụ thành lời giải cụ thể; điều đáng giữ là khoảnh khắc bạn tự nối điều kiện, vị trí và thứ tự thao tác thành một bước đúng.'),section('Hướng dẫn nằm trong bố cục và phản hồi','COCOON giới thiệu cơ chế trong một tình huống đủ gọn để người chơi đọc được nguyên nhân và kết quả. Âm thanh, chuyển động và trạng thái của vật thể giúp biết thao tác đã được nhận hay chưa. Nhờ đó, một nút tương tác vẫn đủ để xây nhiều bài toán mà không kéo theo giao diện phức tạp.','Sự gọn gàng đôi khi làm game có vẻ dẫn đường rất rõ. Nhưng rõ nơi để đi khác với rõ cách giải. Các cuộc chạm trán và tình huống mới làm việc hiểu quy luật cần được chuyển thành hành động đúng lúc, giữ hành trình không chỉ là việc ngắm một bản thiết kế đẹp.'),section('Chất liệu khiến mỗi lớp thế giới có ngôn ngữ riêng','Bề mặt, ánh sáng và đường nét giúp phân biệt những môi trường trong các quả cầu. Đây là thông tin hữu ích cho trí nhớ: bạn có thể gắn một quy tắc với một diện mạo cụ thể. Mỹ thuật vì vậy hỗ trợ suy luận, không chỉ phủ một lớp trang trí lên câu đố.','Game ngắn và không dựa vào việc làm lại để tăng độ dài. Sau khi đã hiểu lời giải, phần hấp dẫn chính sẽ thay đổi. Hãy xem COCOON như một chuỗi ý tưởng được triển khai chặt chẽ; giá trị của nó nằm ở chất lượng những bước hiểu ra, không phải số buổi cần dành để hoàn thành.')],verdict:'COCOON làm một tương tác nhỏ phát triển thành cách nghĩ về cả thế giới. Nó có bản sắc vì hình ảnh, hướng dẫn và cấu trúc câu đố cùng phục vụ một ý tưởng lồng nhau. Chơi ít biết trước sẽ giữ được phần thưởng đáng giá nhất.',fit:'Thích giải đố không lời, thiết kế gọn và những quy tắc nối qua nhiều không gian.',caution:'Ngắn, ít lý do chơi lại và không có cốt truyện đối thoại rõ ràng.'}
});
Object.assign(module.exports,{
'undertale':{theme:'Lòng trắc ẩn và lựa chọn',lede:'Một trận đấu RPG thường bắt đầu bằng câu hỏi đánh ai trước. Undertale thêm một câu hỏi khác: liệu có cần đánh không? Trong khung nhỏ của trận chiến, hành vi và lời nói của một sinh vật có thể quan trọng ngang với lượng máu. Từ đó, game làm những thói quen rất quen thuộc bỗng trở nên đáng nghi.',chapters:[section('Underground không chỉ có những kẻ chặn đường','Một đứa trẻ rơi xuống thế giới của quái vật và tìm đường trở lại mặt đất. Tiền đề đơn giản dành chỗ cho những nhân vật có giọng riêng, từ sự ân cần đến những trò đùa vụng về. Họ không chỉ là phần thưởng hội thoại sau trận đánh; việc hiểu tính cách có thể thay đổi chính cách bạn xử lý cuộc chạm trán.','Undertale dùng sự hài hước để tạo gần gũi trước khi hỏi chuyện nghiêm túc. Một chi tiết tưởng là trò đùa có thể quay lại trong ngữ cảnh khác. Bởi vậy, tóm tắt hết các nhánh kết thúc sẽ làm bài review đánh mất điều nó nên bảo vệ: cảm giác tự nhận ra lựa chọn trước đó có ý nghĩa.'),section('ACT và MERCY khiến chiến đấu thành chuyện đọc người','Bạn có thể tìm cách trò chuyện, phản ứng đúng với đối thủ hoặc tha thứ, trong khi vẫn phải điều khiển trái tim để tránh đòn. Hai phần này gắn với nhau: hiểu đối thủ không có nghĩa nguy hiểm biến mất ngay. Một lựa chọn nhân hậu vẫn cần kiên nhẫn và chú ý tới tín hiệu trong trận đấu.','Cơ chế khiến việc không gây sát thương trở thành một hành động có cấu trúc, thay vì chỉ là lựa chọn trong đoạn phim. Người chơi phải thử, quan sát phản ứng và đôi khi chịu một tình huống khó thêm chút nữa. Đó là nơi chủ đề được đưa vào thao tác, không chỉ được nói ra bằng chữ.'),section('Game nhớ những điều bạn nghĩ là thử cho biết','Những lựa chọn và cách tiếp cận cuộc hành trình ảnh hưởng tới quan hệ cũng như diễn biến. Undertale thường làm người chơi nghĩ lại về thói quen thử một nhánh rồi tải lại để xem nhánh khác. Cảm giác trách nhiệm xuất hiện vì nhân vật đã được xây như những người có tính cách, không chỉ như bộ phận của hệ thống.','Có thể tò mò về mọi khả năng, nhưng một lần chơi ít biết trước thường đáng giữ. Nếu mắc ở đoạn chiến đấu, tìm hỗ trợ về thao tác sẽ ít lấy đi trải nghiệm hơn xem toàn bộ diễn biến cốt truyện. Điểm mạnh của game không phải cú bất ngờ đơn lẻ mà là việc nhiều lựa chọn nhỏ tích lại.'),section('Pixel đơn giản, âm nhạc có trí nhớ','Tạo hình tiết chế giúp một biểu cảm hoặc một chuyển động ngắn nổi bật. Nhạc gắn với nhân vật và tình huống, rồi được dùng lại theo cách khiến người nghe nhận ra quan hệ giữa các thời điểm. Sự thân thuộc ấy hỗ trợ cảm xúc khi câu chuyện đổi sắc.','Không phải trò đùa nào cũng hợp mọi người, và một số đoạn né đạn yêu cầu phản xạ hơn vẻ ngoài của một RPG theo lượt. Nhưng nếu thích nhân vật, âm nhạc và một game biết chất vấn chính luật của thể loại mình đang dùng, Undertale có rất nhiều điều để đọc giữa những dòng hội thoại.')],verdict:'Undertale khiến việc đối xử với một đối thủ trở thành trung tâm của trải nghiệm. Nó để lòng trắc ẩn có thao tác, có khó khăn và có hệ quả. Hãy giữ sự tò mò với các nhân vật trước khi giữ sự tò mò với các kết thúc.',fit:'Thích RPG giàu nhân vật, lựa chọn đạo đức và hệ thống chiến đấu khác thường.',caution:'Có né đạn, hình ảnh nhấp nháy và humor không hợp mọi gu.'},
'disco-elysium':{theme:'Danh tính và chính trị',lede:'Thức dậy mà không nhớ tên mình đã đủ tệ. Disco Elysium còn để những phần trong đầu thám tử tranh nhau giải thích ông là ai. Trước khi hỏi nhân chứng, bạn phải nghe cơ thể, lòng tự trọng và những ý tưởng kỳ quặc cùng lên tiếng. Điều tra một vụ án trở thành việc thương lượng với chính người đang điều tra.',chapters:[section('Revachol là một thành phố có quá khứ chưa chịu yên','Một vụ án ở Martinaise đưa thám tử tới những con người đang sống giữa xung đột lao động, ký ức chính trị và những thất bại cá nhân. Môi trường có chất hội họa, nhưng các chi tiết quan trọng không chỉ nằm trong phong cảnh. Cách một người nói về công việc hoặc một công trình bỏ hoang cho thấy lịch sử vẫn ảnh hưởng tới hiện tại.','Kim Kitsuragi tạo một điểm tựa rõ ràng bên cạnh nhân vật chính thiếu ổn định. Mối quan hệ này giúp câu chuyện có đối trọng: người chơi được phép kỳ quặc, nhưng vẫn cảm nhận một người khác đang quan sát và cùng chịu hệ quả của cách mình hành xử.'),section('Kỹ năng cũng có thể là giọng nói không đáng tin','Các kỹ năng tác động lên quan sát và hội thoại, đồng thời chen vào bằng suy nghĩ. Tăng một khả năng không nhất thiết chỉ làm bạn tốt hơn theo một nghĩa đơn giản. Nó có thể làm một giọng nói mạnh hơn, đẩy cách diễn giải sự kiện về một phía và khiến người chơi phải hỏi liệu có nên tin lời khuyên ấy.','Hệ thống biến xây dựng nhân vật thành cách chọn một loại ý thức. Không có nhu cầu dùng mọi cuộc gặp để thắng theo một khuôn duy nhất. Một thám tử nhạy với cảm xúc sẽ đọc một căn phòng khác người chỉ chăm chú vào lập luận, và chính sự khác biệt đó tạo giá trị chơi lại.'),section('Thất bại có thể mở một đoạn văn đáng đọc','Kiểm tra bằng xúc xắc đặt bất định vào hành động và đối thoại. Game thường cho thất bại một tình huống mới, thay vì chỉ một thông báo thử lại. Điều ấy không có nghĩa mọi lựa chọn đều vô hại, nhưng khiến người chơi có lý do để chấp nhận một phiên bản vụng về của nhân vật thay vì liên tục tải lại.','Disco Elysium đòi hỏi đọc và nghe nhiều. Chính trị, bạo lực, nghiện và tuyệt vọng xuất hiện trong nội dung, nên không phải một chuyến điều tra thư giãn nhẹ. Sức hấp dẫn nằm ở việc những chủ đề ấy gắn với người cụ thể, không chỉ tồn tại như các nhãn ý tưởng.'),section('The Final Cut cho văn bản thêm một giọng nói','Diễn xuất giọng nói giúp các nhân vật và những suy nghĩ nội tâm có nhịp khác nhau. Âm nhạc và hình ảnh giữ một nỗi mệt mỏi khó gọi tên trong thành phố. Bởi vậy, một khoảng đi bộ giữa hai cuộc phỏng vấn có thể là thời gian để điều vừa nghe ngấm xuống.','Đừng bước vào chỉ vì nghe game được gọi là RPG nổi tiếng. Nếu không thích văn bản dài, sự phong phú ấy sẽ thành gánh nặng. Nhưng nếu muốn nhập vai qua ngôn ngữ, ý thức và lựa chọn, Revachol cho một loại chiều sâu khó thay bằng một hệ thống chiến đấu nhiều nút.')],verdict:'Disco Elysium để vụ án và danh tính soi vào nhau. Những giọng nói, cuộc gặp và thất bại có thể tạo một thám tử không hoàn hảo nhưng rất riêng. Đọc chậm là cách cho thành phố và nhân vật đủ thời gian để trở nên phức tạp.',fit:'Thích nhập vai bằng hội thoại, điều tra và chủ đề xã hội nhiều lớp.',caution:'Rất nhiều chữ; nội dung trưởng thành và có thể nặng cảm xúc.'},
'papers-please':{theme:'Đạo đức trong bộ máy',lede:'Tên đúng, ngày đúng, dấu đúng. Papers, Please có thể trông như công việc rà giấy tờ đơn giản, cho đến khi người đứng bên kia bàn giải thích vì sao họ cần qua. Đồng hồ vẫn chạy. Cuối ca, gia đình bạn vẫn cần tiền. Một việc hành chính trở thành cách game đặt lòng tốt và sinh tồn vào cùng một khoảng thời gian ngắn.',chapters:[section('Grestin nhìn thế giới qua một cửa sổ hẹp','Bạn làm người kiểm soát nhập cảnh của Arstotzka sau khi được chọn qua một cuộc xổ số lao động. Vị trí này nhỏ trong bộ máy, nhưng mỗi con dấu có ảnh hưởng trực tiếp tới một người. Game không trao quyền tự do của người hùng; nó trao một bàn làm việc, quy định và trách nhiệm với gia đình.','Sự giới hạn góc nhìn là một phần ý nghĩa. Bạn thường không thấy trọn vẹn cuộc sống của người đang nộp hồ sơ. Một lời kể có thể chân thật, một giấy tờ có thể giả, và quy định mới có thể làm thứ hợp lệ hôm qua trở nên sai hôm nay. Phán đoán vì vậy luôn phải sống cùng sự thiếu thông tin.'),section('Thao tác lặp dần trở thành kỹ năng có áp lực','So ngày, ảnh, tên và các thông tin phát sinh yêu cầu một quy trình kiểm tra. Khi quy định phức tạp lên, mặt bàn nhỏ phải chứa nhiều công cụ và tài liệu hơn. Người chơi học cách sắp xếp việc nhìn, đưa giấy qua lại và gọi sự khác biệt ra trước khi quyết định.','Điều thú vị không nằm ở việc giả vờ công việc giấy tờ luôn vui. Chính sự mệt của công việc khiến một sự cố có sức nặng. Bạn có thể hiểu điều đúng cần làm nhưng không đủ thời gian để làm hoàn hảo, và một sai sót nhỏ liên hệ ngay với thu nhập cuối ngày.'),section('Lòng tốt có một khoản mục trong ngân sách','Các nhu cầu ở nhà làm quyết định tại cửa khẩu không thể tách khỏi tiền. Nhượng bộ một trường hợp có thể tạo hậu quả nghề nghiệp; giữ quy định có thể làm một người bên ngoài chịu thiệt. Game không cần đặt mọi tình huống thành câu hỏi đạo đức to tiếng, bởi cơ chế đã làm lựa chọn có giá.','Các nhánh diễn biến khuyến khích người chơi nhìn lại vai trò của mình, nhưng bài này không liệt kê kết thúc hay các bước mở chúng. Giá trị nằm ở việc bạn tự đối diện một trường hợp trong ca làm, trước khi biết nó thuộc nhánh nào trong một bảng hướng dẫn.'),section('Mỹ thuật lạnh giữ sự nặng nề ở gần','Pixel, âm thanh đóng dấu và không gian chật tạo một nhịp rất khác game quản lý có giao diện vui vẻ. Nhân vật hiện ra ngắn, nhưng đủ để cửa sổ không chỉ là đường nhập dữ liệu. Chỉ một câu nói trước khi rời bàn cũng có thể khiến quyết định vừa làm khó quên.','Papers, Please có nội dung trưởng thành và một áp lực cố ý tạo khó chịu. Nó không phải lựa chọn tốt nếu điều bạn cần là giảm căng thẳng cuối ngày. Nhưng như một thiết kế đặt chính trị và đạo đức vào thao tác thường nhật, chiếc bàn nhỏ này có nhiều thứ để suy nghĩ hơn vẻ ngoài của nó.')],verdict:'Papers, Please làm một con dấu có trọng lượng bằng cách giữ hậu quả ở cả hai phía cửa sổ. Sự lặp không chỉ là công việc; nó là môi trường khiến một lựa chọn tử tế trở nên khó. Đây là game nên đọc như một trải nghiệm gây suy nghĩ, không phải một công việc dễ chịu.',fit:'Thích quyết định đạo đức, mô phỏng công việc và câu chuyện phân nhánh.',caution:'Áp lực thời gian, nội dung trưởng thành và lặp thao tác có chủ đích.'}
});
Object.assign(module.exports,{
'return-of-the-obra-dinn':{theme:'Suy luận từ chứng cứ',lede:'Không có nhân chứng ngồi đợi bạn phỏng vấn. Trên Obra Dinn, người điều tra phải bước vào những khoảnh khắc cuối rồi đọc một cảnh đông người đã đóng băng. Một giọng nói, đôi giày hay vị trí đứng có thể là manh mối. Game tin rằng người chơi đủ khả năng tự suy ra, và không vội biến suy luận ấy thành một đường chỉ dẫn sáng trên sàn.',chapters:[section('Sáu mươi danh tính, một hồ sơ bảo hiểm','Con tàu mất tích trở lại với nhiều câu hỏi hơn câu trả lời. Vai trò của bạn là xác định danh tính và số phận của những người từng ở trên tàu. Cuốn sổ và chiếc đồng hồ tạo hai cách nhìn cùng sự việc: một bên là hồ sơ có ô trống, một bên là những con người trong tình huống cụ thể.','Sự đối lập ấy khiến việc điền đúng một cái tên có ý nghĩa. Bạn đang khôi phục một mối liên hệ, không chỉ chọn đáp án từ danh sách. Lịch sử con tàu mở ra theo thứ tự phát hiện, nên những sự kiện ban đầu khó hiểu có thể được đọc lại sau một cảnh ở nơi khác.'),section('Nghe trước khi nhìn, nhìn trước khi đoán','Âm thanh dẫn vào một cảnh và gợi quan hệ giữa các nhân vật. Sau đó, người chơi tự chọn hướng nhìn để kiểm tra vị trí, trang phục và hành động. Không phải mọi manh mối đều ở ngay gần sự kiện chính; nhìn quanh là một phần bắt buộc của suy luận.','Game xác nhận các nhóm đáp án đúng thay vì lập tức báo từng lựa chọn. Cơ chế này giúp tránh thói quen điền thử mọi tên. Nhưng nó cũng có thể khiến một suy luận đúng phải chờ trong sổ, và người chơi cần chịu được cảm giác chưa có phản hồi ngay.'),section('Một kết luận cần nhiều chi tiết đỡ phía dưới','Niềm vui nằm ở việc một giả thuyết có thêm chứng cứ: chức vụ, lời gọi, một địa điểm ngủ hoặc một nhóm thường xuất hiện cạnh nhau. Các cảnh hỗ trợ nhau, khiến cuốn sổ trở thành mạng lưới quan hệ hơn một danh sách câu đố tách biệt.','Tra lời giải sẽ lấy đi phần thưởng chính. Nếu bế tắc, ghi những điều chắc và những điều mới chỉ nghi là cách giữ suy luận có trật tự. Phân biệt chứng cứ với cảm giác giúp những bước tiếp theo bớt trở thành đoán mò.'),section('Một bit màu vẫn đủ dựng chiều sâu','Hình ảnh gợi máy tính cũ nhưng môi trường ba chiều cho phép đi quanh một cảnh. Sự tiết chế màu không làm nhân vật giống hệt nhau; tư thế, trang phục và bố cục vẫn là thông tin. Âm nhạc tạo lực cho các phát hiện mà không cần cắt cảnh phô trương.','Phong cách này có thể gây mỏi mắt hoặc khó đọc với một số người. Các cảnh chết và bạo lực cũng là phần nội dung cần cân nhắc. Nếu thích suy luận bằng quan sát chi tiết, chính sự gọn về hình ảnh lại giúp chiếc tàu trở thành một hồ sơ dễ giữ trong đầu.')],verdict:'Obra Dinn dành phần việc quan trọng nhất cho người chơi: tự nối chứng cứ. Chiếc đồng hồ chỉ mở một khoảnh khắc, còn ý nghĩa của khoảnh khắc đó phải được xây qua quan sát và sự cẩn trọng.',fit:'Muốn điều tra thật sự bằng danh tính, âm thanh và bằng chứng thị giác.',caution:'Khó, ít gợi ý; đồ họa một bit và cảnh chết có thể gây khó chịu.'},
'balatro':{theme:'Xây động cơ điểm số',lede:'Balatro dùng những bộ bài quen để đưa bạn vào một trò không hẳn là poker. Không cần đọc nét mặt đối thủ; cần đọc khả năng tương tác của Joker, loại tay bài và những hiệu ứng vừa mua. Một bộ đôi yếu có thể trở thành trung tâm của cả lượt chơi nếu bạn tìm được hệ thống làm nó mạnh lên.',chapters:[section('Poker là bảng chữ cái, Joker là ngữ pháp','Tay bài quyết định nền tảng điểm, nhưng các Joker và những lá hỗ trợ làm quy tắc ấy phát triển. Mục tiêu không chỉ là rút một tay hiếm. Nó là tìm cách tạo điểm đủ ổn định để vượt yêu cầu của từng Blind, trong số lượt đánh và lượt bỏ có hạn.','Vì không đấu trực tiếp với một người khác, giá trị của tay bài được đặt vào kế hoạch của chính bạn. Có lúc đôi là hợp lý hơn cố đợi một sảnh. Balatro biến kiến thức poker thành điểm bắt đầu, rồi khuyến khích người chơi sẵn sàng bỏ thói quen chọn tay đẹp theo cảm giác.'),section('Cửa hàng là nơi một lượt chơi nhận hình dạng','Tiền có thể dùng mua sức mạnh ngay, đổi lựa chọn hoặc giữ để tận dụng kinh tế về sau. Một món hiếm chưa chắc hợp với Joker đang có. Quyết định có ý nghĩa khi bạn hiểu nó tăng nền điểm, nhân điểm hay giúp tạo tay bài ổn định.','Các phần thưởng ngẫu nhiên buộc kế hoạch linh hoạt. Bạn có thể muốn một cách xây cụ thể nhưng phải đọc những gì thực sự xuất hiện. Sự cân bằng giữa kỳ vọng và thích ứng làm cửa hàng có sức hút, đồng thời tạo những lượt mà may mắn ảnh hưởng rõ hơn người chơi mong.'),section('Boss Blind hỏi kế hoạch có điểm yếu nào','Một điều kiện thay đổi có thể làm cách ghi điểm đang rất mạnh trở nên khó dùng. Nhờ vậy, hệ thống không chỉ thử con số cao nhất mà còn thử độ bền của chiến lược. Người chơi cần nhớ luật trước khi đánh, thay vì nhận ra quá muộn sau khi đã dùng các lượt bỏ.','Đây là chỗ game gây cảm giác thêm một ván nữa. Bạn thường thấy một lý do cụ thể để làm tốt hơn: mua sai thứ, giữ sai tay hoặc không dự phòng cho điều kiện. Nhưng khi chỉ còn mong cửa hàng đưa đúng món, sự tò mò có thể chuyển thành sự lệ thuộc vào lần rút tiếp theo.'),section('Những con số cũng biết tạo kịch tính','Âm thanh tính điểm và nhịp lần lượt kích hoạt hiệu ứng làm phần thưởng có hình thức rõ. Trình bày gọn giữ sự chú ý vào một bàn bài, nhưng số lượng hiệu ứng có thể khiến người mới khó hiểu vì sao điểm vừa tăng mạnh. Học đọc phép tính là một phần cuộc chơi.','Balatro không cần một cốt truyện tuyến tính để có bản sắc. Câu chuyện của mỗi lượt là quá trình một bộ bài thường nhận một ý tưởng riêng. Nếu muốn nhân vật và hội thoại, game không cung cấp điều ấy; nếu thích hệ thống có thể uốn theo lựa chọn, bàn bài rất nhỏ này có nhiều đất để thử.')],verdict:'Balatro hấp dẫn ở khoảng cách giữa tay bài nhìn yếu và hệ thống khiến nó ghi điểm lớn. Sức mạnh đến từ hiểu tương tác và quản lý rủi ro, với một phần may mắn không thể xóa hoàn toàn.',fit:'Thích thẻ bài, xây hệ thống và suy nghĩ theo tổ hợp hơn phản xạ.',caution:'Ngẫu nhiên có ảnh hưởng; dễ chơi lâu hơn dự tính và cần đọc rõ luật Boss.'},
'slay-the-spire':{theme:'Tiết chế và chiến lược',lede:'Sau một trận thắng, Slay the Spire hỏi bạn có lấy thêm một lá không. Câu trả lời không luôn là có. Bộ bài càng lớn, những lá cần ở đúng lúc càng có thể nằm xa hơn. Game xây chiều sâu từ một nghịch lý dễ hiểu: phần thưởng giúp mạnh lên, nhưng chọn quá nhiều phần thưởng có thể làm kế hoạch yếu đi.',chapters:[section('Đường lên tháp bắt đầu trước trận đánh','Bản đồ cho thấy những tuyến đi qua trận đấu, sự kiện, cửa hàng và điểm nghỉ. Chọn đường là đánh giá sức hiện tại cùng phần thưởng muốn tìm. Một trận Elite có thể cho lợi ích tốt, nhưng cái giá mất máu sẽ theo bạn tới các nút sau.','Cấu trúc ấy nối những quyết định nhỏ thành chiến lược dài. Không cần một cốt truyện nhiều hội thoại để chuyến leo có cá tính: bạn có thể nhớ lượt đó vì một relic đổi cả kế hoạch hoặc một lần nghỉ đã cứu phần cuối.'),section('Ý định của đối thủ tạo cơ hội tính trước','Game cho thấy điều đối thủ chuẩn bị làm, giúp chọn giữa gây sát thương, phòng thủ và thiết lập lượt sau. Năng lượng giới hạn khiến một tay có nhiều lá tốt vẫn cần ưu tiên. Quyết định có giá trị vì bạn nhìn được một phần hậu quả nhưng không có toàn bộ lá bài trong tay.','Nhờ thông tin này, thất bại thường có chỗ để phân tích. Bạn đã bỏ qua ý định, dùng hết năng lượng sai lúc hay xây bộ bài thiếu khả năng bảo vệ? Sự rõ ràng không làm game dễ; nó làm việc học có căn cứ.'),section('Một lá bị loại có thể đáng hơn một lá được thêm','Loại những lá cơ bản hoặc từ chối phần thưởng làm bộ bài nhất quán hơn. Các nhân vật có cơ chế khác nhau, nên một ý tưởng hiệu quả ở lượt này không phải khuôn chung cho mọi lượt. Relic và nâng cấp còn làm giá trị một lá thay đổi theo ngữ cảnh.','Nếu cố xây đúng một bộ bài từ đầu, ngẫu nhiên sẽ gây nhiều bực. Nhìn phần thưởng như lời gợi ý thay vì mệnh lệnh giúp việc thích ứng thú vị hơn. Game thưởng cho một kế hoạch có thể sửa, không chỉ cho kiến thức về một tổ hợp được cộng đồng tối ưu.'),section('Độ khó cao hơn thử khả năng hiểu hệ thống','Các mức thử thách tạo thêm áp lực cho những nguyên tắc đã học. Ở đây, biết một lá mạnh không đủ; còn phải biết lúc nào nó giúp giải vấn đề trước mắt. Cảm giác tiến bộ nằm trong chất lượng quyết định, kể cả khi lượt chơi vẫn kết thúc sớm.','Trình bày và hoạt ảnh tiết chế khiến việc đọc lá và ý định dễ hơn một màn hình nhiều hiệu ứng. Người cần câu chuyện nhân vật hoặc hành động trực tiếp có thể thấy nhịp này khô. Nhưng ai thích nhìn một quyết định nhỏ ảnh hưởng cả chặng đường sẽ có nhiều lý do để trở lại tháp.')],verdict:'Slay the Spire tạo chiến thuật từ việc chọn, từ chối và sửa kế hoạch. Nó không yêu cầu bàn tay nhanh; nó yêu cầu bạn hiểu vì sao một bộ bài nên gọn hơn, và vì sao đường khó nhất chưa chắc là đường tốt nhất.',fit:'Thích deckbuilding, đọc ý định đối thủ và những quyết định dài hạn.',caution:'Nhiều lần thử; thắng không bảo đảm dù kế hoạch tốt và ít cốt truyện tuyến tính.'}
});
Object.assign(module.exports,{
'inscryption':{theme:'Luật chơi và sự nghi ngờ',lede:'Người chia bài ngồi ở phía tối của căn chòi. Trên bàn là sinh vật, máu và một hệ thống trông đủ rõ để bắt đầu tính toán. Nhưng Inscryption liên tục nhắc rằng căn phòng cũng thuộc cuộc chơi. Nếu chỉ nhìn tay bài, bạn có thể bỏ qua điều đang lặng lẽ làm luật của trận đấu trở nên bất ổn.',chapters:[section('Một trò chơi thẻ có người chủ trì quá nhiều quyền','Tiền đề đặt người chơi vào một bàn đấu với đối thủ bí ẩn. Cách ông ta nói, đưa luật và phản ứng tạo cảm giác không cân xứng: bạn có thể học hệ thống nhưng chưa chắc biết hệ thống ấy phục vụ ai. Sự căng thẳng này làm mỗi chiến thắng có thêm một dấu hỏi.','Bài này giữ kín các chuyển hướng quan trọng. Inscryption dùng việc thay đổi cách hiểu chính trò chơi để kể chuyện, nên tóm tắt đầy đủ sẽ lấy đi nhiều hơn một nút thắt. Điều có thể nói là hãy xem căn phòng, âm thanh và các vật thể như thông tin, không chỉ như lớp trang trí kinh dị.'),section('Hy sinh tạo một nền kinh tế có hình ảnh rõ','Các sinh vật và tài nguyên đặt việc chơi một lá vào quan hệ với những lá đang có. Hy sinh có thể tạo một đơn vị mạnh, nhưng cũng làm mất khả năng bảo vệ hoặc gây sát thương ở một đường khác. Bàn đấu nhỏ khiến hậu quả của lựa chọn dễ nhìn thấy.','Ký hiệu và hiệu ứng trên lá làm chiến thuật phát triển hơn nền tảng ấy. Một cách kết hợp tốt có thể đổi giá trị của một sinh vật yếu. Tuy nhiên, cảm giác đọc luật chưa đầy đủ là một phần game cố tạo; người muốn thẻ bài cân bằng và ổn định như đấu xếp hạng có thể không thích việc câu chuyện can thiệp.'),section('Đứng dậy khỏi bàn cũng là một nước đi','Các câu đố và chi tiết trong căn phòng nối phần điều tra với trận đấu. Sự tò mò được khuyến khích bằng việc cho người chơi nhìn quanh, thử đồ vật và nghĩ tới quan hệ giữa những thứ không nằm trên mặt bàn. Nhờ đó, kinh dị có nhịp đổi chứ không chỉ dựa vào một đối thủ đáng sợ.','Nếu bế tắc, hãy ghi lại thứ đã thấy và thứ chưa giải thích được. Tìm một gợi ý nhỏ thường giữ được trải nghiệm hơn xem một video trọn vẹn. Inscryption đặc biệt dễ mất sức hút khi người chơi biết trước vì sao mọi chi tiết xuất hiện.'),section('Âm thanh và vật liệu làm bộ bài bớt vô hại','Bàn gỗ, những vật dụng kỳ lạ và ánh sáng hạn chế khiến việc cầm bài có một chất vật lý khó chịu. Phản hồi âm thanh tạo cảm giác một lựa chọn không chỉ thay số mà còn tác động lên một vật trong căn phòng.','Nội dung kinh dị, hình ảnh gây bất an và sự cố ý làm người chơi nghi ngờ luật là những điều cần cân nhắc. Inscryption hợp với người muốn thẻ bài phục vụ một bí ẩn. Nó không đơn thuần là một bộ bài đáng sưu tầm được đặt trên nền tối.')],verdict:'Inscryption khiến việc hiểu luật và việc tin luật trở thành hai câu hỏi khác nhau. Hãy đến vì sự kết hợp giữa chiến thuật trên bàn và tò mò trong phòng, rồi giữ các phát hiện lớn cho chính lần chơi của bạn.',fit:'Thích thẻ bài, câu đố trong phòng và kinh dị có trò chơi với kỳ vọng.',caution:'Dễ bị spoiler; có kinh dị và quy tắc không luôn ổn định.'},
'baba-is-you':{theme:'Ngôn ngữ và quy luật',lede:'Một bức tường trong game thường là giới hạn. Trong Baba Is You, nó còn là một từ có thể đẩy. Khi WALL IS STOP bị phá, bạn không vừa mở khóa một vật phẩm: bạn vừa đổi cách thế giới hoạt động. Câu đố bắt đầu từ việc dám xem câu chữ như một phần địa hình.',chapters:[section('Chủ ngữ và thuộc tính cùng nằm trên sàn','Các khối từ tạo thành câu xác định ai được điều khiển, thứ gì chặn đường và điều kiện thắng là gì. Người chơi vừa di chuyển nhân vật vừa sắp lại ngữ pháp. Một đổi chỗ nhỏ có thể khiến vật thể quen mang một thuộc tính khác, làm toàn bộ màn chơi nhận hình dạng mới.','Game không dựa vào một cốt truyện tuyến tính. Bản sắc nằm trong quan hệ giữa ngôn ngữ và hành động: một câu đúng không chỉ mô tả thế giới, nó thực sự tạo luật cho thế giới. Vì vậy, đọc màn chơi cần nhìn cả vật thể lẫn những mệnh đề đang giữ chúng ở trạng thái hiện tại.'),section('Lời giải thường bắt đầu bằng việc đổi câu hỏi','Khi đường đi bị chặn, bản năng là tìm cách mở cửa. Baba Is You thường hỏi liệu cửa có cần còn là cửa, bạn có cần còn là Baba hay điều kiện thắng có thể đổi. Các câu đố mạnh nhất làm người chơi nhận ra một giả định mình tự mang vào màn.','Sự đảo cách nghĩ tạo những phát hiện rất vui, nhưng cũng khiến game khó theo một hướng khác với phản xạ. Bạn có thể hiểu tất cả từ mà chưa thấy quan hệ đúng. Nghỉ rồi quay lại với một câu hỏi khác thường có ích hơn đẩy mọi khối một cách ngẫu nhiên.'),section('Hoàn tác giữ thử nghiệm có giá thấp','Khả năng quay lại thao tác trước giúp người chơi thử một giả thuyết mà không phải chịu một đoạn làm lại dài. Nhưng đẩy một khối vào góc vẫn cho thấy giới hạn không gian rất cụ thể. Ngữ pháp tự do luôn phải làm việc với vị trí, thứ tự và chỗ trống.','Điều đó giữ Baba Is You khỏi trở thành một bài đố chữ thuần túy. Một câu mong muốn chưa chắc dựng được trong căn phòng. Người chơi phải tìm cách bảo toàn những từ cần thiết trong khi thay luật, biến suy luận trừu tượng thành một kế hoạch di chuyển chính xác.'),section('Hình ảnh gọn để ý tưởng có chỗ nổi bật','Tạo hình và âm thanh ít phô trương giúp tập trung vào trạng thái và quan hệ. Khi một thuộc tính đổi, việc nhận ra phản hồi rất quan trọng: bạn cần biết luật mới đã được áp dụng, chứ không chỉ mong nó đúng.','Baba Is You không thích hợp nếu bạn muốn hướng dẫn từng bước hoặc dùng cốt truyện làm động lực vượt đoạn khó. Nó hợp với người thấy một ý tưởng vừa hiểu ra là phần thưởng đủ lớn. Đây là trò chơi về những giả định nhỏ, được hỏi đến tận cùng.')],verdict:'Baba Is You biến quy tắc thành thứ người chơi phải thao tác. Độ sâu đến từ việc không còn xem một bức tường, một nhân vật hay chữ chiến thắng là những điều cố định.',fit:'Thích logic, suy nghĩ ngoài giả định và thử nghiệm có thể hoàn tác.',caution:'Rất khó về suy luận; ít câu chuyện và không liên tục chỉ đường.'},
'noita':{theme:'Thí nghiệm và hậu quả',lede:'Một vũng dầu nhỏ có thể là vật liệu, một lối thoát hoặc nguyên nhân của tai nạn. Noita cho vật chất phản ứng ở cấp pixel, rồi trao cho người chơi những chiếc đũa có thể tự lắp phép. Tự do này rất rộng, nhưng game không hứa sẽ bảo vệ bạn khỏi một ý tưởng nghe có vẻ thông minh.',chapters:[section('Thế giới vật chất không chờ người chơi cho phép','Lửa, chất lỏng và các vật liệu tác động qua lại, khiến môi trường trở thành hệ thống đang hoạt động. Một tác động nhỏ có thể lan xa hơn điều bạn nhìn lúc bắt đầu. Vì vậy, quan sát điều đang ở quanh đối thủ quan trọng ngang với nhìn đối thủ.','Noita không mở đầu bằng một kịch bản giải thích mọi bí mật. Cách kể nằm trong các địa điểm và những điều có thể khám phá sâu hơn vòng lặp cơ bản. Người chơi có thể chỉ muốn một lượt đi hang, hoặc dần thấy bản đồ có những tầng ý nghĩa không lộ ngay.'),section('Cấu trúc đũa quyết định phép chạy ra sao','Ghép phép và các yếu tố điều chỉnh tạo một không gian thử nghiệm lớn. Thứ tự, khả năng của đũa và cách các phép tương tác có thể làm một cấu hình khác hẳn tổng những món đang lắp. Niềm vui là tìm được một hiệu ứng hiệu quả, nhưng cũng phải hiểu vì sao nó vận hành như vậy.','Đọc lướt thông tin có thể rất đắt. Một cấu hình gây nguy hiểm gần người dùng hoặc một hiệu ứng không phù hợp môi trường có thể kết thúc lượt chơi. Game làm kiến thức trở thành phần phòng thủ quan trọng: biết một phép có thể làm gì vẫn chưa đủ, còn phải biết nó có thể làm gì sai.'),section('Thất bại không luôn lịch sự giải thích','Các tương tác vật lý tạo tình huống khó lường. Có lúc bạn nhìn ra nguyên nhân rất rõ, có lúc chỉ thấy mọi thứ diễn biến nhanh hơn khả năng phản ứng. Sự bất định ấy là sức hút và cũng là điểm khiến Noita có thể gây nản.','Giá trị học không nên bị nhầm với sự công bằng hoàn toàn. Người muốn tiến trình ổn định có thể thấy những lượt kết thúc bất ngờ quá tốn thời gian. Người thích thí nghiệm sẽ thường có một giả thuyết mới để thử, nhưng nên chấp nhận rằng game không biến mọi khám phá thành một phần thưởng an toàn.'),section('Pixel ở đây là vật liệu, không chỉ là phong cách','Hình ảnh nhỏ gọn cần đọc được trạng thái vật chất: chỗ đang cháy, thứ có thể đổ xuống và vùng nước có tính chất khác. Hiệu ứng đẹp vì chúng là dấu hiệu một hệ thống đang vận hành, không phải chỉ vì chúng lấp đầy màn hình.','Noita có thể tạo màn hình rất bận và các chuỗi phản ứng mạnh. Đi chậm ở nơi chưa hiểu giúp quan sát có giá trị hơn liên tục đẩy sâu. Nếu muốn tự do thử những thứ game khác thường khóa lại, những chiếc đũa ở đây có đủ khả năng làm bạn bất ngờ, theo cả hai nghĩa.')],verdict:'Noita trao tự do đi kèm hậu quả thật. Một phép mạnh có thể là sản phẩm của hiểu biết, nhưng cái chết cũng có thể là một bài học vật lý. Nó đáng khám phá khi bản thân việc thí nghiệm đã là niềm vui.',fit:'Thích vật lý mô phỏng, ghép phép và khám phá bí mật sâu.',caution:'Khó, có thất bại bất ngờ và cần đọc kỹ nhiều tương tác.'}
});
Object.assign(module.exports,{
'gris':{theme:'Màu sắc và mất mát',lede:'GRIS không mở đầu bằng một nhiệm vụ nói rõ phải cứu ai. Nó đưa một giọng hát vào không gian rồi để thế giới mất đi sự vững chắc. Khi màu sắc trở lại từng phần, hành trình có cảm giác như học cách đứng trong một đời sống vừa đổi khác, hơn là hoàn thành những ô trên một bản đồ.',chapters:[section('Một câu chuyện không cần gắn nhãn từng cảm xúc','Nhân vật đi qua các cảnh tượng gợi mất mát, bất lực và chuyển biến. GRIS giữ cách kể mở, để hình ảnh và âm nhạc tạo liên hệ thay vì giải thích rõ một sự kiện theo ngôn ngữ hội thoại. Người chơi có thể đọc những biểu tượng theo trải nghiệm của mình.','Sự mở ấy không có nghĩa mọi cảnh là hình đẹp đặt cạnh nhau. Nhịp xuất hiện của màu, khả năng và những trở ngại tạo một hướng phát triển. Game cho người chơi thấy một trạng thái thay đổi, nhưng giữ đủ khoảng riêng để cảm xúc không trở thành một kết luận bị áp đặt.'),section('Chiếc váy đưa cảm xúc vào chuyển động','Các khả năng của chiếc váy ảnh hưởng việc vượt địa hình và tương tác với môi trường. Một thay đổi trong cách nhân vật đứng vững hoặc di chuyển làm trải nghiệm có lớp hành động, không chỉ là một phim ngắn cho phép đi tới. Câu đố đưa bạn đọc lại khung cảnh theo công cụ vừa có.','Thử thách nhìn chung nhường chỗ cho dòng chảy. Ai thích platformer chính xác sẽ thấy phần điều khiển ít đòi hỏi hơn kỳ vọng. Đây là lựa chọn có chủ đích: game muốn giữ sự chú ý ở chuyển biến của không gian, không dùng việc thua nhiều để quyết định nhịp cảm xúc.'),section('Màu là tiến trình, không chỉ là bảng trang trí','Việc một màu mới xuất hiện làm môi trường nhận sắc thái khác, và khiến người chơi nhìn lại điều vừa đi qua. Màu có vai trò như ngôn ngữ kể chuyện: nó thể hiện một bước chuyển mà không cần nhân vật nói mình đang cảm thấy thế nào.','Âm nhạc cùng phát triển với hình ảnh, tạo các đoạn lên xuống đủ rõ để hành trình có cấu trúc. Một khoảnh khắc đẹp hiệu quả vì trước đó đã có sự thiếu hụt hoặc chờ đợi. Nếu chỉ xem ảnh lẻ, bạn sẽ bỏ qua phần quan hệ giữa các cảnh làm vẻ đẹp có ý nghĩa.'),section('Ngắn để một nét vẽ không bị kéo thành công việc','GRIS có thể được trải nghiệm trong một khoảng chơi ngắn, và các yếu tố phụ không biến nó thành một hệ thống thu thập khổng lồ. Điều đó giúp giữ một đường cảm xúc tương đối liền. Dừng lại ngắm một cảnh thường có giá trị hơn đi tìm cách tăng số giờ.','Sự tiết chế cũng là giới hạn. Người cần nhân vật được phát triển bằng đối thoại hoặc muốn lựa chọn ảnh hưởng câu chuyện sẽ không thấy điều ấy ở đây. Hãy chọn GRIS vì cách nó dùng hình ảnh và chuyển động, chứ không vì mong một RPG nghệ thuật với nhiều nhánh cốt truyện.')],verdict:'GRIS để màu sắc và động tác nhỏ kể một hành trình cảm xúc. Nó không cần làm mọi biểu tượng có một đáp án duy nhất. Khoảng yên và sự ngắn gọn giúp những bước chuyển có thời gian ở lại.',fit:'Muốn hành trình thị giác, âm nhạc và câu chuyện cảm xúc không lời.',caution:'Ngắn, ít độ khó và cách kể biểu tượng không giải thích trực tiếp.'},
'blasphemous':{theme:'Sùng tín và thân thể',lede:'Chiếc mũ gai của Penitent One cho thấy Cvstodia không định kể một câu chuyện nhẹ. Tại đây, lòng sùng tín có thể trở thành hình dạng của một cơ thể, một công trình hoặc một hình phạt. Blasphemous tạo bản sắc không chỉ bằng độ khó, mà bằng việc cả thế giới nhìn như đang mang một món nợ chưa được trả.',chapters:[section('The Miracle không phải một lời giải đơn giản','Người sám hối đi qua Cvstodia, nơi những biểu tượng tôn giáo, đau đớn và biến dạng gắn với đời sống. Các nhân vật thường nói như đang sống trong một lịch sử dài mà người mới tới chưa hiểu. Câu chuyện không được trao thành một bản giải thích ngắn trước khi chiến đấu.','Điều đáng khai thác là sự nhập nhằng: một điều được xem là ân huệ có thể đồng thời tạo đau khổ. Môi trường và lời kể làm người chơi đặt câu hỏi về ý nghĩa của sám hối, thay vì chỉ theo dấu một phản diện rõ ràng. Bài này tránh giải thích các kết thúc để giữ tính bất định của hành trình.'),section('Đọc tầm đánh trước khi tin vào sự lì đòn','Chiến đấu có nhịp và trọng lượng rõ. Chặn, né và chọn thời điểm phản công quan trọng hơn việc liên tục tiến vào tầm đối thủ. Các tình huống địa hình còn khiến một quyết định vội có hậu quả lớn hơn lượng sát thương của một đòn.','Sự căng thẳng này phù hợp với diện mạo thế giới, nhưng không phải mọi khó chịu đều đáng gọi là chiều sâu. Việc đi lại và các nguy hiểm môi trường có thể làm một chuyến khám phá bị ngắt. Người chơi nên biết game yêu cầu sự cẩn trọng cả ngoài các trận đấu quan trọng.'),section('Khám phá là đọc một kiến trúc của niềm tin','Các khu vực nối với nhau qua đường đi và những điều kiện cần hiểu. Bí mật thường gắn với vật phẩm, nhân vật hoặc việc quay lại một chỗ trong ngữ cảnh mới. Nhờ vậy, khám phá không chỉ là điền thêm vùng tối mà là học một thế giới có logic riêng.','Tuy nhiên, nhiệm vụ và một số điều kiện có thể mơ hồ. Nếu cần mục tiêu rõ ràng liên tục, bạn dễ cảm thấy phải tra cứu. Một gợi ý vừa đủ có thể giữ sự tò mò, trong khi danh sách lời giải đầy đủ sẽ làm những cuộc gặp chỉ còn là bước thực hiện.'),section('Pixel art không làm hình ảnh bớt dữ dội','Chi tiết của thân thể, công trình và hoạt ảnh tạo một mỹ thuật rất nhận diện. Âm nhạc cùng không khí nghi lễ giúp các vùng có cảm giác trang nghiêm ngay khi chúng đáng sợ. Đây là nơi hình thức và chủ đề làm việc sát nhau.','Nội dung bạo lực và hình ảnh kinh dị cơ thể đáng cân nhắc, dù hình ảnh được dựng bằng pixel. Blasphemous hợp với người muốn một metroidvania có ngôn ngữ thị giác mạnh, không chỉ với người muốn đo mình có chịu được độ khó cao hay không.')],verdict:'Blasphemous biến sám hối thành cảnh quan và nhịp chiến đấu. Những giới hạn về chỉ dẫn và sự khắc nghiệt có thể cản một số người, nhưng Cvstodia có bản sắc vì mọi lớp đều mang cùng một sức nặng.',fit:'Thích metroidvania, chiến đấu cẩn trọng và mỹ thuật tôn giáo u tối.',caution:'Có body horror, bạo lực, chỉ dẫn mơ hồ và nguy hiểm địa hình.'},
 'this-war-of-mine':{theme:'Dân thường trong chiến tranh',lede:'Một game chiến tranh thường trao vũ khí và mục tiêu. This War of Mine bắt đầu bằng thiếu thốn: một căn nhà hỏng, vài người cần ăn và đêm đang tới. Bạn không có cách thắng chiến tranh. Bạn chỉ có những quyết định về việc sống qua hôm nay mà vẫn còn đủ sức sống qua ngày mai.',chapters:[section('Căn nhà là trung tâm, không phải hậu phương vô hình','Những người sống sót có tình trạng cơ thể, tinh thần và khả năng khác nhau. Ban ngày, việc sửa chữa và chế tạo tạo ra các điều kiện để căn nhà tiếp tục vận hành. Một giường, một bếp hoặc vật liệu dự phòng vì thế có sức nặng khác hẳn đồ trang trí.','Câu chuyện không chỉ nằm trong sự kiện lớn. Nó nằm trong người phải nằm nghỉ, bữa ăn phải chờ và cuộc tranh luận về thứ nên làm. Đặt người dân thường ở trung tâm giúp chiến tranh hiện ra qua những nhu cầu không thể tạm bỏ để chạy theo một nhiệm vụ anh hùng.'),section('Một chuyến ra ngoài luôn có phần phải bỏ lại','Ban đêm, chọn người đi và người ở nhà là quyết định về rủi ro. Sức mang có hạn khiến thuốc, thức ăn và vật liệu cạnh tranh nhau. Người đi tìm đồ cũng không luôn bước vào một kho vô chủ; địa điểm có thể có người đang sống hoặc những nguy hiểm cần tránh.','Không gian của túi đồ làm ưu tiên có hình dạng rõ. Mang một món có thể nghĩa là để một món khác lại cho chuyến sau, nếu còn chuyến sau. Những lựa chọn nhỏ khiến bài toán tài nguyên không tách khỏi việc biết mình đang lấy từ đâu.'),section('Sinh tồn và lương tâm không dùng chung một thước đo','Một hành động có lợi trước mắt có thể để lại hậu quả tinh thần. Game không cho việc tối ưu tài nguyên trở thành câu trả lời đầy đủ, bởi các nhân vật là con người phải sống với điều đã làm. Sự mâu thuẫn ấy tạo chiều sâu mà một bảng điểm thắng thua không thể hiện hết.','Đồng thời, This War of Mine có thể rất nặng nề. Thiếu thốn liên tục và các tình huống đạo đức không phải thử thách giải trí nhẹ. Chọn một khoảng chơi phù hợp với trạng thái cảm xúc của mình là điều hợp lý, không phải bỏ lỡ tinh thần của game.'),section('Một bảng màu giữ mọi thứ ở trạng thái mệt mỏi','Hình ảnh và âm thanh tạo sự lạnh, thiếu ổn định và mong manh trong căn nhà. Không khí hỗ trợ việc đọc điều kiện sống: một khoảng nghỉ có thể chỉ là tạm yên, chứ chưa phải an toàn. Các khoảng im lặng làm sức nặng của quyết định khó trôi đi nhanh.','Game có những cơ chế có thể học và tối ưu, nhưng nhìn nó chỉ như bài toán hoàn hảo sẽ bỏ qua chủ đề. Điều đáng nhớ thường là một lựa chọn mà bạn hiểu vì sao phải làm, nhưng vẫn không thấy dễ chịu sau đó.')],verdict:'This War of Mine đưa hậu quả chiến tranh vào giường ngủ, bữa ăn và những chuyến đi đêm. Nó đáng trải nghiệm khi bạn muốn một game sinh tồn đặt con người ngang với tài nguyên, và sẵn sàng cho một nhịp chơi khó nhẹ lòng.',fit:'Quan tâm sinh tồn, lựa chọn đạo đức và góc nhìn dân thường.',caution:'Nội dung chiến tranh nặng cảm xúc; thất bại và thiếu thốn liên tục.'}
});
Object.assign(module.exports,{
'frostpunk':{theme:'Quyền lực trong khủng hoảng',lede:'Nhiệt độ giảm không cần một bài diễn văn để gây sợ. Frostpunk đặt máy phát ở giữa thành phố, rồi để bạn nhìn các khu dân cư như những vòng tròn cần được giữ ấm. Ban đầu là quyết định ai làm việc ở đâu. Sau đó, những quyết định ấy trở thành luật, và lời hứa sống sót bắt đầu đòi một cái giá khác.',chapters:[section('Máy phát là trái tim và cũng là giới hạn','Thành phố phải cân đối nhiên liệu, nơi ở và các công trình trong một môi trường lạnh khắc nghiệt. Địa hình xoay quanh nguồn nhiệt khiến việc quy hoạch có quan hệ trực tiếp với sinh mạng. Một vị trí thuận tiện về sản xuất chưa chắc đủ tốt để người làm việc ở đó giữ sức.','Bởi các hệ thống phụ thuộc nhau, một thiếu hụt có thể lan: ít than làm lạnh hơn, lạnh làm người bệnh hơn, người bệnh làm việc ít hơn. Game giữ áp lực bằng những liên kết ấy, không chỉ bằng một con số nhiệt độ đang giảm ở góc màn hình.'),section('Một điều luật không chỉ là phần thưởng mở khóa','Book of Laws cho phép giải quyết vấn đề bằng những quy tắc có hậu quả xã hội. Các phương án có thể hứa hiệu quả rõ, nhưng lời mô tả và phản ứng của dân khiến lợi ích không còn vô hình. Người chơi đang định hình một cộng đồng, không chỉ tăng chỉ số.','Frostpunk mạnh khi bạn nhận ra lựa chọn hôm qua tạo cách suy nghĩ hôm nay. Một ngoại lệ dễ chấp nhận có thể làm bước tiếp theo bớt gây ngần ngại. Chính quá trình ấy đáng phân tích hơn việc liệt kê luật nào tối ưu cho một kịch bản.'),section('Hy vọng là một tài nguyên không thể đào bằng cuốc','Cư dân cần tin lời hứa và chịu được điều kiện sống. Nhiệm vụ, bất mãn và hy vọng khiến quyền lãnh đạo có phản hồi. Một lời hứa tưởng dễ để làm dịu tình hình có thể trở thành nghĩa vụ rất khó khi thời tiết hoặc sản xuất đổi.','Sự khó chịu có chủ đích tạo tính khẩn cấp, nhưng cũng dễ làm người mới cảm thấy phải học bằng cách thua cả một kịch bản. Tạm dừng để đọc các mối phụ thuộc là cách quan trọng để biến khủng hoảng thành những vấn đề có thể xử lý từng bước.'),section('Hơi ấm có thể đẹp mà vẫn không đủ','Âm thanh, tuyết và ánh sáng làm máy phát có sức hút thị giác rất rõ. Từ xa, thành phố trông có trật tự; ở gần, từng khu vực vẫn có nhu cầu chưa được đáp ứng. Sự đối lập giữ câu hỏi về quyền lực ở trong hình ảnh của việc quản lý.','Game không phải lựa chọn thư giãn cho người thích dựng thành phố theo ý mà không có áp lực. Nếu muốn thử khả năng quản lý cùng câu hỏi mình sẵn sàng biến cộng đồng thành gì để sống sót, Frostpunk có một khung thiết kế đủ mạnh để giữ câu hỏi đó đến cuối.')],verdict:'Frostpunk làm việc xây thành phố trở thành việc lập một trật tự xã hội trong khủng hoảng. Thành công về tài nguyên không tự trả lời liệu cái giá đã chấp nhận có đáng hay không.',fit:'Thích xây dựng có áp lực, hệ thống liên kết và lựa chọn xã hội.',caution:'Khó, cần học qua thất bại; nội dung khủng hoảng và các lựa chọn nặng nề.'},
'darkwood':{theme:'Giữ một nơi trú ẩn',lede:'Trong Darkwood, một ngôi nhà không an toàn vì trên bản đồ nó được gọi là chỗ trú. Nó an toàn vì bạn đã chặn cửa, chuẩn bị nhiên liệu và còn đủ chú ý để nghe điều bên ngoài. Nỗi sợ xuất hiện từ khoảng cách giữa công việc đã làm và thứ vẫn không thể biết chắc.',chapters:[section('Khu rừng không mở đường theo mong muốn','Người chơi khám phá một môi trường méo mó, với các nhân vật và địa điểm làm sự bình thường khó giữ nguyên. Góc nhìn từ trên xuống cho thấy nhiều mặt bằng nhưng không trao tầm hiểu biết tuyệt đối. Ánh sáng và hướng quan sát vẫn quyết định thứ có thể đọc.','Câu chuyện đi qua những cuộc gặp khó tin và dấu vết trong rừng. Không có nhu cầu giải thích ngay nguồn gốc của mọi điều lạ. Darkwood xây cảm giác bạn đang sống trong một nơi có luật, nhưng chưa đủ hiểu luật ấy để thấy yên tâm.'),section('Ngày là lúc chuẩn bị, đêm là lúc kiểm tra','Ban ngày, tìm tài nguyên và chọn đường thám hiểm phục vụ khả năng chống chịu ban đêm. Việc mang về đồ gì ảnh hưởng cách sửa, chế tạo và tổ chức nơi trú. Khi trời tối, những khoảng trống trong chuẩn bị có thể trở thành điều bạn phải xử lý ngay.','Vòng lặp làm thời gian có ý nghĩa nhưng không chỉ bằng đồng hồ. Càng đi xa, khả năng mang về lợi ích càng lớn và đường trở lại càng có giá. Darkwood hỏi người chơi lúc nào đủ là đủ, trong một thế giới liên tục làm câu trả lời thay đổi.'),section('Âm thanh cho thông tin, không trao sự chắc chắn','Tiếng động bên ngoài có thể báo nguy hiểm hoặc làm trí tưởng tượng đi trước thực tế. Giữ vị trí, nhìn hướng cần thiết và quyết định có dùng tài nguyên phòng thủ hay không tạo một kiểu căng thẳng kéo dài. Không phải nỗi sợ nào cũng cần hiện ngay thành một sinh vật trên màn hình.','Game tránh dựa hoàn toàn vào chuỗi giật mình, nhưng điều đó không khiến nó nhẹ. Sự chờ đợi, bạo lực và kinh dị cơ thể có thể rất khó chịu. Đây là game nên chọn vì muốn một không khí ngột ngạt, không chỉ vì tò mò về một nhãn kinh dị phổ biến.'),section('Sự khan hiếm khiến hành động nhỏ có giá','Đồ dùng, sức khỏe và lối đi làm mỗi trận chạm trán cần được cân nhắc. Không phải đối thủ nào cũng đáng đánh nếu tài nguyên phải phục vụ một đêm sắp tới. Game có sự khắc nghiệt làm quá trình học chậm, đôi khi dễ thành bực nếu bạn chưa đọc được nguy hiểm.','Hình ảnh tiết chế không làm các cảnh vật ít ám ảnh; nó cho phần âm thanh và bóng tối nhiều chỗ. Người thích quản lý chuẩn bị và tự khám phá sẽ tìm được chiều sâu. Người cần chỉ dẫn liên tục hay hồi phục nhanh sau sai sót có thể thấy khu rừng quá kín.')],verdict:'Darkwood biến chỗ trú thành một công việc phải duy trì. Nỗi sợ của nó nằm trong việc đã chuẩn bị rất nhiều mà vẫn không thể chắc mình chuẩn bị đúng. Sự căng thẳng ấy là bản sắc, đồng thời là giới hạn tiếp cận rõ ràng.',fit:'Thích survival horror, âm thanh gây áp lực và quản lý nơi trú.',caution:'Ngột ngạt, bạo lực, chỉ dẫn ít và thất bại có giá.'},
'limbo':{theme:'Sự mong manh trong bóng tối',lede:'Một hình dáng nhỏ bước vào khu rừng, và LIMBO không giải thích thêm. Chiếc bẫy trên đất, bóng nhện và khoảng tối trước mặt đều cần được đọc từ chuyển động. Game dùng hai màu để giữ một cảm giác rất rõ: nhân vật có thể bước tiếp, nhưng thế giới không có nghĩa vụ báo trước điều sẽ xảy ra.',chapters:[section('Câu chuyện tồn tại trong hướng đi và sự vắng mặt','Một cậu bé tìm chị gái trong một thế giới không được đặt tên đầy đủ. Không có hội thoại dài để xác định nơi này là gì. Hình ảnh và trình tự gặp gỡ tạo bối cảnh, để người chơi tự nối cảm giác về nguy hiểm, cô độc và mục đích.','Cách kể mở giúp game giữ sự ám ảnh sau khi hết, nhưng không bảo đảm mọi người có cùng cách hiểu. Nếu cần một kết luận giải thích các biểu tượng, LIMBO có thể để lại sự thiếu hụt. Điều nó làm chắc hơn là cho hành trình một giọng riêng mà không cần chữ.'),section('Thử nghiệm vật lý bằng một cơ thể rất dễ tổn thương','Đẩy, kéo và di chuyển qua các cơ chế biến câu đố thành hành động cụ thể. Bạn học trọng lượng, khoảng cách và thời điểm qua phản hồi. Chướng ngại không chỉ yêu cầu hiểu ý tưởng; còn cần đưa nhân vật qua ở đúng nhịp.','Nhiều nguy hiểm được biết rõ sau lần đầu thất bại. Cách thiết kế ấy tạo bất ngờ và cho thế giới vẻ không thân thiện, nhưng cũng có thể gây khó chịu vì người chơi chưa có đủ thông tin để tránh. Những điểm trở lại gần giúp giảm thời gian làm lại, không xóa hoàn toàn tính thử sai.'),section('Bóng và chiều sâu làm hai màu có nhiều sắc thái','Các lớp nền tạo khoảng cách trong một thế giới gần như không dùng màu. Ánh sáng xác định thứ có thể nhận ra, còn âm thanh môi trường khiến một cảnh tĩnh vẫn có chuyển động ở ngoài tầm nhìn. Sự tiết chế giữ mỗi hình dáng lạ nổi bật.','Phong cách cũng hỗ trợ sự bất định: thứ trông như vật trang trí có thể thành nguy hiểm khi bạn lại gần. LIMBO làm mắt phải học cách nhìn, nhưng không nên đọc mọi khoảng tối như một câu đố có đáp án biểu tượng chính xác.'),section('Một hành trình ngắn với nhịp không luôn đồng đều','Khu rừng tạo một ấn tượng mạnh ngay đầu, trong khi các phần cơ chế về sau chuyển trọng tâm sang suy luận và thời điểm. Sự thay đổi cho game nhiều loại tình huống, nhưng người thích nỗi sợ hữu cơ ban đầu có thể thấy không khí đã khác.','Game có cảnh chết của nhân vật trẻ và bạo lực dù hình ảnh chỉ là bóng. Quy mô ngắn phù hợp việc trải nghiệm tương đối liền, để âm thanh và sự vắng lặng không bị quên giữa quá nhiều lần tạm nghỉ.')],verdict:'LIMBO không cần nhiều lời để làm một bước đi có vẻ nguy hiểm. Hai màu và các cơ chế vật lý tạo một hành trình mong manh, với thử sai vừa là phương pháp học vừa là điểm cần cân nhắc.',fit:'Thích platformer giải đố, kể chuyện không lời và không khí tối giản.',caution:'Ngắn, có chết bất ngờ và cảnh bạo lực với nhân vật trẻ.'}
});
Object.assign(module.exports,{
'inside':{theme:'Kiểm soát và phục tùng',lede:'Cậu bé chạy qua một khu rừng trong mưa, tránh ánh đèn và những người không cần giải thích vì sao đang đuổi theo. INSIDE giữ người chơi ở một vị trí dễ tổn thương ngay từ đầu. Càng đi vào sâu, câu hỏi dần đổi: ai đang kiểm soát những chuyển động mình tưởng là lựa chọn?',chapters:[section('Không lời thoại, nhưng thế giới có tổ chức','Hàng rào, xe cộ và những nhóm người chuyển động cho thấy một xã hội đang vận hành theo quy tắc. Nhân vật chính không được trao tiểu sử đầy đủ. Người chơi đọc điều bất thường qua việc cậu phải trốn, qua cách cơ thể khác hành động và qua cấu trúc của những khu vực liên tiếp.','Bài này không giải thích phần kết. INSIDE dựa nhiều vào việc các hình ảnh làm cách hiểu trước đó thay đổi. Giữ câu hỏi mở là cần thiết, bởi sự bất an đến từ việc đã thấy một hệ thống nhưng chưa biết mình nằm ở đâu trong nó.'),section('Câu đố điều khiển cơ thể, rồi điều khiển kỳ vọng','Đẩy, kéo, canh nhịp và tương tác với thiết bị tạo những bài toán có tính vật lý. Một cơ chế có thể làm các cơ thể khác chuyển động theo bạn, biến chủ đề kiểm soát thành thao tác cụ thể. Việc giải câu đố vì thế không đứng ngoài ngôn ngữ của thế giới.','Các tình huống được dựng để dẫn mắt và hướng thử nghiệm, nhưng vẫn có đoạn cần biết nguy hiểm qua thất bại. Điểm trở lại gần giảm thời gian làm lại. Tuy nhiên, người không thích thử sai hoặc cảnh chết của nhân vật trẻ nên cân nhắc trước khi xem vẻ đẹp điện ảnh là lý do đủ để bắt đầu.'),section('Chuyển cảnh liên tục giữ một dòng bất an','INSIDE dùng chiều sâu, ánh sáng và chuyển động nền để tạo cảm giác môi trường tồn tại ngoài đường đi của nhân vật. Một hành động ở xa có thể báo điều sắp xảy ra mà không cần giao diện nhắc nhở. Âm thanh vật liệu khiến một cú bước hoặc cú va chạm có trọng lượng.','Game ít dùng lời để cắt nhịp. Nhờ vậy, một khoảng đi bộ có thể giữ câu hỏi từ cảnh trước sang cảnh sau. Sự liền mạch là điểm mạnh, nhưng cũng làm lựa chọn tự do tương đối hạn chế: bạn đang theo một hành trình được đạo diễn rất chặt, không thám hiểm một thế giới mở.'),section('Đẹp không có nghĩa là dễ chịu','Tạo hình tiết chế và bảng màu u tối làm hình ảnh rất nhận diện. Vẻ lạnh và sự chính xác của hoạt ảnh khiến các sự kiện bất thường càng khó đọc như chuyện ngẫu nhiên. Cảm giác rằng mọi thứ có chủ đích có thể mạnh hơn một cú giật mình.','Quy mô ngắn và kết thúc không giải thích trực tiếp có thể khiến người cần một câu chuyện khép kín thấy hụt. Nhưng nếu thích việc hình ảnh tiếp tục tạo câu hỏi sau khi đã đặt tay điều khiển xuống, INSIDE có một cách dẫn trải nghiệm ít cần lời mà vẫn rất rõ giọng.')],verdict:'INSIDE đặt câu hỏi về kiểm soát vào chính chuyển động của người chơi. Sự chặt của dàn dựng và sự mở của ý nghĩa cùng tạo bản sắc; đây là hành trình nên tự xem đến cuối trước khi đọc bất kỳ lời giải thích nào.',fit:'Thích kể chuyện thị giác, câu đố vật lý và chủ đề phản địa đàng.',caution:'Có cảnh chết, bạo lực, thử sai và kết thúc cố ý để mở.'},
'va-11-hall-a':{theme:'Lắng nghe trong một đô thị',lede:'Khách có thể nói về công việc, tình cảm hoặc một ngày kỳ quặc. Jill không chọn một câu trả lời trong bảng hội thoại; cô chọn nguyên liệu, trộn đồ uống và để cuộc trò chuyện tiếp tục. VA-11 Hall-A biến một quầy bar nhỏ thành nơi thành phố được kể lại từ những người đang cố sống trong nó.',chapters:[section('Glitch City hiện ra qua khách quen','Bối cảnh cyberpunk có các cấu trúc xã hội và công nghệ lớn, nhưng góc nhìn ở quán giữ câu chuyện sát đời thường. Những người ghé qua mang theo công việc, quan hệ và các vấn đề riêng. Thành phố được hiểu qua tác động lên họ, không chỉ qua một đoạn mô tả thế giới.','Jill cũng có đời sống ngoài ca làm, nên việc lắng nghe không biến cô thành một cái máy ghi chuyện. Khoảng ở nhà và những suy nghĩ của nhân vật làm các ca nối với nhau. Điều ấy giúp câu chuyện giữ một trục cảm xúc ngay khi khách nói về rất nhiều điều khác nhau.'),section('Một công thức là một cách phản hồi','Đồ uống có thành phần, lượng và cách pha cần thực hiện. Khách có thể đưa một yêu cầu rõ hoặc nói theo cách phải hiểu ý. Thao tác pha tạo một khoảng ngắt nhỏ trong dòng văn bản, khiến người chơi tham gia mà không làm cuộc trò chuyện thành một bài kiểm tra phản xạ.','Các lựa chọn liên quan đồ uống ảnh hưởng diễn biến trong ngữ cảnh. Game không biến mọi thay đổi thành một biển báo lớn rằng bạn vừa chọn nhánh. Sự tinh tế phù hợp với quầy bar, nhưng người muốn quyền can thiệp rõ vào mọi đoạn hội thoại có thể cảm thấy phạm vi hành động nhỏ.'),section('Nhiều chữ cần nhiều giọng khác nhau','Humor, chuyện riêng và các đề tài trưởng thành tạo những sắc thái không đồng nhất. Một cuộc trò chuyện có thể rất đời thường rồi chuyển sang điều khó chịu mà không rời chiếc ghế ở quầy. Giá trị nằm ở việc khách có cá tính, không chỉ đại diện cho một ý tưởng về tương lai.','Đây vẫn là visual novel đọc nhiều. Nếu không thích nhịp hội thoại dài, hệ thống pha đồ uống sẽ không đủ biến trải nghiệm thành game quản lý sâu. Hãy chọn nó vì muốn nghe những người này nói, không vì mong tối ưu một quán bar đông khách bằng bảng tài chính.'),section('Âm nhạc biến căn phòng thành một nơi quen','Pixel art và các bản nhạc tạo vẻ neon có chất ấm hơn một đô thị chỉ toàn kim loại lạnh. Việc ở lại cùng một không gian qua nhiều ca giúp các chi tiết trở nên thân thuộc. Quán là chỗ tạm dừng trong thành phố, nhưng không làm mọi vấn đề của khách biến mất.','Nội dung có ngôn ngữ và đề tài người lớn. Cách viết đôi khi phóng túng có thể không hợp mọi gu. Tuy vậy, chính việc không giữ mọi nhân vật lịch sự theo một khuôn làm những cuộc trò chuyện có chất sống, với khoảng cách và sự gần gũi thay đổi qua thời gian.')],verdict:'VA-11 Hall-A đưa cyberpunk về một quy mô đủ nhỏ để lắng nghe. Cơ chế pha đồ uống không phải điểm hấp dẫn độc lập; nó là nhịp để con người và những câu chuyện trong Glitch City có chỗ ngồi.',fit:'Thích visual novel, đối thoại đời thường và âm nhạc cyberpunk.',caution:'Đọc nhiều, cơ chế đơn giản và nội dung trưởng thành.'},
'katana-zero':{theme:'Ký ức bị cắt dựng',lede:'Một nhát kiếm, một viên đạn được trả lại và căn phòng vừa đông đã im. Katana ZERO có thể trông như một bài toán làm sạch màn chơi bằng tốc độ. Nhưng giữa các lần hành động, các cuộc trò chuyện và mảnh ký ức làm câu hỏi về nhân vật trở nên khó giữ yên. Việc tua lại không chỉ là tiện ích; nó thuộc cách câu chuyện nhìn thời gian.',chapters:[section('Người sát thủ không nắm trọn câu chuyện của mình','Những nhiệm vụ và cuộc gặp đưa nhân vật qua một đô thị neon, trong khi ký ức và việc điều trị tạo một phần đời sống khó tin chắc. Câu chuyện được cắt theo các mảnh, để những điều nghe hợp lý lúc đầu có thể nhận sắc thái khác về sau.','Review nên giữ các liên hệ quan trọng chưa được giải thích. Katana ZERO có sức hút vì hành động rất rõ ràng đối lập với thông tin về chính người hành động còn thiếu. Nói hết lịch sử của nhân vật sẽ làm sự đối lập đó chỉ còn là một thủ pháp đã được báo trước.'),section('Một phòng nhỏ là bài toán về thứ tự','Nhân vật mong manh, nên đường di chuyển và thời điểm xử lý đối thủ quyết định nhiều hơn lượng máu dự trữ. Phản đạn, né và tận dụng vật thể tạo các cách giải khác nhau cho cùng một tình huống. Làm chậm thời gian giúp đọc một khoảnh khắc, nhưng vẫn cần kế hoạch trước khi lao vào.','Khi thua, thử lại nhanh giữ cảm giác đang dựng một chuỗi hành động. Bạn có thể sửa đúng bước vừa sai thay vì đi lại nhiều phút. Niềm vui nằm ở một lần thực hiện sạch, nhưng cũng có đoạn phải thử đủ nhiều để thuộc bố cục, nên phản xạ và trí nhớ cùng tham gia.'),section('Hội thoại cũng có nhịp, không chỉ có đáp án','Các lựa chọn trong trò chuyện và khả năng ngắt lời làm nhân vật có cách hiện diện khác nhau. Không phải mọi đoạn ngoài chiến đấu là thời gian chờ tới màn tiếp theo. Chúng xây sự bất ổn, thái độ và quan hệ mà các trận đánh không thể tự giải thích.','Nhịp này có thể làm người chỉ muốn hành động thấy bị ngắt, nhưng bỏ qua nó sẽ khiến game mất một phần giọng riêng. Katana ZERO dùng sự dồn dập và khoảng chậm để hai lớp thời gian soi vào nhau, thay vì giữ tốc độ tối đa suốt hành trình.'),section('Neon và synth phục vụ một thế giới khó ngủ','Hình ảnh pixel, hoạt ảnh và âm nhạc tạo những đoạn hành động có chất điện ảnh. Ánh sáng giúp bối cảnh hiện đại rõ mà không cần quá nhiều chi tiết, còn âm thanh giữ cảm giác mỗi đòn chạm có tác động.','Game có bạo lực mạnh và câu chuyện không giải thích hết mọi điều trong một vòng gọn. Người cần kết thúc hoàn toàn khép kín có thể thấy còn chờ. Nếu thích chiến đấu ngắn, chính xác cùng một bí ẩn về danh tính và thời gian, sự chưa yên ấy là phần sức hút của nó.')],verdict:'Katana ZERO dùng tốc độ để tạo sự chắc chắn trong hành động, rồi dùng ký ức để làm sự chắc chắn ấy lung lay. Những lần thử lại mạnh nhất khi được đọc cùng câu chuyện, không chỉ như bài tập phản xạ.',fit:'Thích hành động chính xác, thử lại nhanh và thriller neo-noir.',caution:'Có bạo lực, nội dung trưởng thành và các câu hỏi chưa khép kín.'}
});
Object.assign(module.exports,{
'broforce':{theme:'Hỗn loạn có thể chơi cùng',lede:'Broforce không giữ địa hình nguyên vẹn để bạn có một đường đi sạch. Một loạt đạn có thể mở lối, một vụ nổ có thể làm mất nền đang đứng và người bạn vừa cứu có thể kéo cả nhóm vào một tai nạn mới. Game biến việc vượt màn thành câu chuyện mà kế hoạch thường chỉ sống được vài giây.',chapters:[section('Một đội hành động được dựng bằng sự quá đà','Các nhân vật gợi những hình tượng phim hành động, mỗi người có vũ khí và khả năng khác. Việc đổi nhân vật sau cứu người khiến màn chơi nhận nhịp mới ngay trong lúc tiến lên. Bạn không chỉ mở thêm một chiếc skin; bạn phải dùng một cách tấn công khác trong cùng môi trường đang bị phá.','Humor phóng đại tạo giọng rõ, nhưng không cần coi mọi vụ nổ là một ý tưởng chiến thuật sâu. Broforce mạnh khi sự ngớ ngẩn và quyết định có ích cùng tồn tại. Một hành động làm cả nhóm cười có thể cũng là hành động đã mở được lối đi nhanh hơn.'),section('Phá cảnh vật là công cụ và cũng là rủi ro','Địa hình phản ứng khiến việc bắn có tác dụng vượt ngoài đối thủ. Một vật dễ nổ có thể giúp xử lý nhóm địch, nhưng cũng làm vị trí an toàn biến mất. Người chơi phải đọc mối quan hệ giữa vật thể thay vì chỉ nhìn đường đi được đặt sẵn.','Bởi phản ứng dây chuyền có thể xảy ra rất nhanh, một thất bại không luôn tạo cảm giác kiểm soát tuyệt đối. Đó là phần đánh đổi của sự hỗn loạn. Người thích platformer có bố cục luôn rõ và lỗi luôn do thao tác của mình có thể thấy game quá ồn.'),section('Co-op cần chấp nhận đồng đội có thể là biến số','Chơi cùng thêm cơ hội cứu, hỗ trợ và phối hợp các vũ khí. Nó cũng thêm người có thể làm nổ đúng thứ bạn đang đứng cạnh. Một màn vượt thành công có thể là phối hợp tốt, hoặc một chuỗi xử lý ứng biến sau khi kế hoạch ban đầu đã hỏng.','Điều quan trọng là cả nhóm cùng muốn nhịp vui ấy. Nếu một người cố hoàn hảo và người khác muốn thử mọi vật thể, sự khác biệt có thể thành bực. Broforce hợp với buổi chơi chấp nhận tiếng cười và thử lại là phần cuộc vui, không chỉ là phần bị tính vào thời gian hoàn thành.'),section('Pixel vẫn đủ để màn hình rất đông','Hoạt ảnh và hiệu ứng làm mỗi nhân vật có phản hồi mạnh. Âm thanh góp vào vẻ quá đà của hành động, khiến một đoạn ngắn có thể như cao trào. Tuy nhiên, nhiều người và nhiều vụ nổ cùng xuất hiện có thể làm thông tin khó đọc.','Có bạo lực phóng đại và những hình tượng châm biếm không hợp mọi gu. Game vẫn chơi được một mình, nhưng phần ứng biến xã hội sẽ khác. Hãy chọn theo loại buổi chơi bạn muốn có: một chuỗi màn hành động nhanh hay một kế hoạch mà cả nhóm vui khi nó sụp đổ.')],verdict:'Broforce dùng môi trường phá hủy và nhân vật thay đổi để tạo những đoạn hành động khó giữ nguyên kế hoạch. Co-op làm sự bất định vui hơn khi cả nhóm chấp nhận cùng sửa một tai nạn do chính mình tạo.',fit:'Muốn co-op hành động, phá địa hình và humor phim hành động.',caution:'Màn hình hỗn loạn, chết nhanh và nội dung bạo lực phóng đại.'},
'sifu':{theme:'Thời gian và luyện tập',lede:'Nhân vật đứng dậy sau một lần thua, nhưng không đứng dậy ở cùng tuổi. Sifu cho thất bại một dấu vết rất cụ thể trên cơ thể. Đường trả thù vì thế không chỉ là tiến tới đối thủ cuối; nó là học cách đi qua những đoạn đã biết với ít cái giá hơn.',chapters:[section('Tuổi tác khiến tiến trình không đi theo một chiều','Câu chuyện trả thù đưa nhân vật qua các địa điểm và đối thủ quan trọng. Cơ chế tuổi tác làm mỗi lần hồi sinh vừa là cơ hội vừa là mất mát. Bạn có thể tiếp tục một đoạn, nhưng mang theo hệ quả của những trận trước đó.','Điều ấy thay đổi ý nghĩa việc quay lại màn. Làm tốt hơn một chặng cũ có thể mở cơ hội thực sự cho chặng sau. Sifu không chỉ hỏi đã tới đâu; nó hỏi tới đó ở trạng thái nào. Cảm giác tiến bộ nằm trong chất lượng hành trình, không chỉ vị trí cuối.'),section('Võ thuật được đọc qua khoảng cách và cấu trúc','Đỡ, né, gạt và phản công có vai trò khác nhau. Thanh cấu trúc khiến việc chịu áp lực và phá thế đối thủ trở thành bài toán rõ. Nhấn liên tục có thể tạo chuyển động đẹp, nhưng để giữ thế trận cần hiểu lúc nào đối thủ đang chuẩn bị ra đòn và loại phản ứng nào phù hợp.','Các nhóm địch còn yêu cầu chọn vị trí. Đứng ở đâu quyết định ai có thể áp sát và bạn có công cụ môi trường nào để dùng. Khi game bắt đầu dễ hơn, lý do thường là đọc tình huống tốt hơn, không phải mọi cú đánh đã tự mạnh lên đủ để bỏ qua quy tắc.'),section('Một lối tắt không thay thế việc học đối thủ','Khám phá và mở đường giúp các lần quay lại bớt lặp nguyên vẹn. Tuy nhiên, phần khó quan trọng vẫn cần kỹ năng đọc và thực hiện. Sifu làm việc luyện một tình huống có giá trị dài hạn vì nó giảm cái giá tuổi tác khi đi qua tình huống đó lần nữa.','Các tùy chọn độ khó hỗ trợ nhiều mức tiếp cận, nhưng nhịp chiến đấu vẫn đòi hỏi chú ý. Người muốn theo câu chuyện một lượt không bị cản nhiều có thể cần điều chỉnh sớm, thay vì chờ sự nản tích lại rồi coi mọi trận là cuộc kiểm tra không cần thiết.'),section('Không gian được dựng như một cảnh võ thuật','Bố cục và vật dụng cho các trận đấu có chất điện ảnh, trong khi chuyển động giữ tác động rõ trên cơ thể. Các địa điểm thay sắc thái làm đường trả thù có nhịp thị giác chứ không chỉ là chuỗi sàn đấu.','Cốt truyện có thể không nhiều lớp bằng hệ thống chiến đấu. Sức hút chính là quá trình một người chơi từ lúng túng thành biết chọn phản ứng. Nếu bạn thấy việc làm một đoạn cũ tốt hơn là một phần thưởng đáng kể, Sifu có cách đo tiến bộ rất trực quan.')],verdict:'Sifu làm thời gian trở thành cái giá mà kỹ năng có thể giảm. Nó hấp dẫn khi bạn muốn luyện chất lượng của từng cuộc chạm trán, và nhìn một đoạn đã biết trở nên gọn hơn qua những lần trở lại.',fit:'Thích võ thuật, làm chủ nhịp phòng thủ và luyện một màn tốt hơn.',caution:'Đòi hỏi luyện tập; câu chuyện gọn hơn chiều sâu chiến đấu.'},
'furi':{theme:'Đối thoại bằng nhịp chiến đấu',lede:'Furi không cho bạn một rừng quái nhỏ để làm nóng trước cuộc đấu quan trọng. Đối thủ đứng đó, luật dần lộ ra qua đòn và mỗi giai đoạn yêu cầu cách đọc mới. Một cuộc vượt ngục được kể bằng những cuộc gặp mà lời nói và chiến đấu cùng hỏi bạn đang đi tới điều gì.',chapters:[section('Người dẫn đường không nói thay mọi ý nghĩa','Nhân vật thoát khỏi giam cầm qua các đấu trường và gặp những người canh giữ. Những đoạn đi bộ cùng hội thoại tạo khoảng để suy nghĩ giữa các cuộc đấu. Game giữ một câu hỏi về mục đích và hậu quả thay vì mở bằng giải thích hoàn chỉnh.','Sự tiết chế phù hợp với cấu trúc boss rush. Mỗi đối thủ có thể để lại một thái độ hoặc câu nói đáng nhớ, nhưng phần lớn thời gian gắn bó đến từ cách họ chiến đấu. Vì vậy, không cần biết trước ý nghĩa cuối hành trình để hiểu giá trị của một cuộc chạm trán.'),section('Khoảng xa và khoảng gần là hai loại câu hỏi','Các phần né đạn và đấu cận chiến đổi trọng tâm chú ý. Ở xa, cần đọc hình của vùng nguy hiểm và tìm đường trống. Ở gần, cần hiểu nhịp gạt, né và phản công. Một đối thủ có thể làm cả hai thay đổi qua giai đoạn, giữ trận không chỉ là lặp một mẫu.','Nhờ cấu trúc rõ, luyện một đoạn có thể cho cảm giác tiến bộ cụ thể. Bạn bắt đầu nhận ra tín hiệu trước khi đòn tới. Nhưng nếu không thích học qua thử nhiều lần, một trận dài sẽ dễ thành rào cản hơn một cuộc đối thoại thú vị.'),section('Một cơ hội hồi phục vẫn cần được giành','Các cơ chế chiến đấu khuyến khích đáp lại nguy hiểm đúng thời điểm, thay vì chỉ chạy tránh cho tới khi tình hình tự tốt. Người chơi phải nhận ra lúc nào nên chủ động. Sự căng thẳng đến từ việc cần hành động khi vẫn chưa hoàn toàn thấy an toàn.','Furi rất phụ thuộc phản xạ và việc đọc chuyển động. Những tùy chọn hỗ trợ có thể giảm áp lực, nhưng người chỉ muốn câu chuyện nên hiểu rằng game không có nhiều nội dung khác để thay thế các trận đấu khi chúng không hợp mình.'),section('Âm nhạc làm đấu trường có một nhịp riêng','Màu mạnh, tạo hình nhân vật và nhạc điện tử làm mỗi trận có chất trình diễn. Những đoạn âm nhạc tăng cường độ có thể làm một pha thực hiện tốt rất đã, nhưng cũng dễ khiến người chơi lao nhanh hơn khả năng quan sát.','Giữ nhịp tỉnh táo giữa sự phô trương là phần kỹ năng. Khoảng đi bộ sau trận vừa cho câu chuyện tiến, vừa trả lại một khoảng thở. Furi có vẻ chỉ gồm các trận đánh, nhưng chính cách đặt khoảng nghỉ làm cao trào tiếp theo giữ được sức nặng.')],verdict:'Furi đặt phần hay nhất của một game hành động vào trung tâm: học một đối thủ, đáp lại đúng nhịp và nhận ra mình đã đọc được điều từng quá nhanh. Âm nhạc và câu chuyện ngắn nâng các trận, không thay thế chúng.',fit:'Thích boss rush, né đạn, parry và âm nhạc điện tử.',caution:'Nhiều lần luyện cùng trận; yêu cầu phản xạ và ít nội dung ngoài đấu.'}
});
Object.assign(module.exports,{
'cult-of-the-lamb':{theme:'Quyền lực và chăm sóc',lede:'Con cừu trở về từ một cuộc chinh phạt với tài nguyên, rồi gặp một vấn đề ít huy hoàng hơn: tín đồ cần ăn và chỗ ở cần dọn. Cult of the Lamb đặt sự dễ thương cạnh quyền lực đáng ngờ. Bạn vừa giữ một cộng đồng hoạt động, vừa quyết định nó sẽ tin và chịu điều gì.',chapters:[section('Một mạng sống được trả bằng một giáo phái','Sau khi được đưa trở lại từ cái chết, nhân vật phải gây dựng những người đi theo để phục vụ kẻ đã cứu mình. Tiền đề khiến việc quản lý có một món nợ phía sau. Những hình dạng tròn và biểu cảm vui không xóa nội dung về sự phục tùng, nghi lễ và quyền định đoạt.','Game dùng sự đối lập để tạo humor đen. Một hoạt động nhìn như chăm sóc có thể cùng lúc củng cố quyền lực. Điều đáng xem không chỉ là cộng đồng lớn tới đâu, mà là những phương tiện người lãnh đạo đã chọn để giữ nó ở trạng thái nghe lời.'),section('Hai vòng lặp cần nhau nhưng không cùng nhịp','Các lượt chinh phạt cung cấp tài nguyên và mở tiến triển, còn căn cứ tạo một nơi để dùng chúng. Chiến đấu ngắn có lựa chọn trang bị, trong khi quản lý yêu cầu theo dõi nhu cầu và công trình. Khi một phía vận hành tốt, nó hỗ trợ nhịp của phía kia.','Tuy nhiên, người chỉ thích chiến đấu có thể thấy việc ở nhà ngắt mạch; người chỉ thích dựng căn cứ có thể không muốn đi đánh thường xuyên. Sức hút nằm ở việc tận hưởng mối nối giữa hai phần, không ở kỳ vọng một trong hai có thể hoàn toàn thay phần còn lại.'),section('Tín đồ là nhu cầu, lòng tin và tính cách','Các thành viên có đặc điểm và phản ứng, làm quản lý không chỉ là đặt thêm nhà. Người chơi cân nhắc đồ ăn, vệ sinh, lòng tin và các quyết định liên quan nghi lễ. Một cộng đồng đông hơn tăng khả năng, nhưng cũng tăng việc phải chú ý.','Cơ chế tạo tình huống vui vì diện mạo hiền và hệ quả không luôn hiền. Nhưng đằng sau humor vẫn có sự lặp của việc duy trì. Nếu bạn nhanh chán các công việc thường nhật trong game quản lý, những hình vẽ duyên dáng không tự làm chúng biến mất.'),section('Mỹ thuật ngọt để ý tưởng đen nổi bật','Hoạt ảnh, hình dáng và âm thanh làm mỗi công việc có phản hồi sống động. Các môi trường chiến đấu thay sắc thái, trong khi khu cộng đồng dần mang dấu của những gì bạn xây. Vẻ đẹp phục vụ cả nhịp hành động lẫn cảm giác sở hữu một nơi chốn.','Nội dung nghi lễ, bạo lực và humor tôn giáo có thể không hợp một số người. Đừng chọn chỉ vì con cừu trên bìa đáng yêu. Cult of the Lamb có duyên vì nó biết dùng sự đáng yêu để làm những lựa chọn không dễ chịu bớt được nhìn bằng một khuôn quen.')],verdict:'Cult of the Lamb gắn nhu cầu chăm sóc với khả năng cai trị. Hai vòng chiến đấu và quản lý tạo phần thưởng qua lại, còn humor đen giữ câu hỏi về quyền lực ở sát những việc rất nhỏ trong căn cứ.',fit:'Thích kết hợp roguelite, quản lý cộng đồng và humor đen.',caution:'Có việc bảo trì lặp, bạo lực và các đề tài nghi lễ/tôn giáo.'},
'nine-sols':{theme:'Báo thù và giới hạn tiến bộ',lede:'Nine Sols gọi thế giới của mình là Đạo punk, và cụm từ ấy có ý nghĩa hơn một bảng màu. Công nghệ, nghi lễ và tham vọng trường sinh cùng hiện diện trong môi trường của Yi. Những cuộc đấu cần gạt đúng nhịp đưa bạn tiến qua thế giới ấy, còn câu chuyện liên tục hỏi điều gì đã bị trả để nó tồn tại.',chapters:[section('Yi mang một món nợ vào New Kunlun','Hành trình hướng tới chín Sols có một lịch sử cá nhân phía sau, được mở dần qua nhân vật và các dấu vết của nền văn minh. Người chơi không chỉ đi tìm đối thủ kế tiếp; họ đang hiểu vì sao Yi có lý do để trở lại và điều cuộc trở lại ấy có thể làm thay đổi.','Cách kết hợp ý tưởng Đạo giáo với khoa học viễn tưởng tạo nhiều câu hỏi về sự sống và quyền lực. Review không cần kể hết các mối quan hệ để cho thấy bản sắc: nhìn cách kiến trúc, máy móc và lời thoại đặt một lời hứa tiến bộ cạnh những giới hạn mà nó không chịu chấp nhận.'),section('Parry là điểm tựa, không phải một tùy chọn phụ','Chiến đấu yêu cầu đọc nhịp và đáp lại đòn đúng thời điểm. Các cách sử dụng khí và bùa nối phòng thủ với khả năng tấn công, khiến việc gạt thành công trở thành cơ hội chủ động. Điều này làm một cuộc đấu có cấu trúc đối thoại: đối thủ ra tín hiệu, người chơi trả lời bằng một thao tác đủ chính xác.','Lao vào đánh liên tục thường không tận dụng được hệ thống. Khi học một boss, phân biệt các chuỗi đòn và biết lúc nào không tham thêm một nhát rất quan trọng. Game có các lựa chọn điều chỉnh để nhiều người theo được câu chuyện, nhưng nhịp parry vẫn là phần bản sắc cần được thử thật.'),section('Thế giới mở ra bằng cả đường đi và thông tin','Khám phá các khu vực nối nhau, có khả năng mới và những nhân vật để gặp tạo cấu trúc metroidvania. Khoảng ngoài chiến đấu giúp câu chuyện có thời gian phát triển, thay vì biến mọi thông tin thành phần thưởng sau một boss.','Các đoạn đi lại và hội thoại có thể làm nhịp chậm so với người chỉ muốn đấu liên tục. Nhưng chúng tạo lý do cho các đối thủ tồn tại trong một thế giới, không chỉ như bài kiểm tra phản xạ. Nine Sols có sức hút khi bạn quan tâm cả việc thắng một cuộc đấu lẫn việc hiểu nó thuộc xung đột nào.'),section('Nét vẽ mềm không làm nội dung mềm đi','Hoạt ảnh và mỹ thuật vẽ tay giúp các chuyển động có trọng lượng mà vẫn dễ nhận tín hiệu. Âm nhạc cùng sự pha trộn vật liệu làm bối cảnh có vẻ riêng, vượt ngoài ý tưởng máy móc tương lai đặt cạnh một vài biểu tượng truyền thống.','Game có bạo lực và các chủ đề nặng về cơ thể, quyền lực, mất mát. Người thấy hình nhân vật đáng yêu không nên mặc định đây là cuộc phiêu lưu nhẹ. Nếu thích một câu chuyện khoa học viễn tưởng có nền tư tưởng và hệ chiến đấu rõ trọng tâm, Nine Sols có nhiều thứ để theo đến cùng.')],verdict:'Nine Sols dùng parry để tạo nhịp chiến đấu và Đạo punk để tạo ngữ cảnh cho nhịp ấy. Yi không chỉ cần một bàn tay chính xác; hành trình còn cần người chơi sẵn sàng nhìn vào những điều một nền văn minh đã chọn bỏ qua.',fit:'Thích parry, metroidvania và truyện khoa học viễn tưởng có chủ đề triết học.',caution:'Boss khó, có bạo lực và các đoạn hội thoại dài đổi nhịp.'},
'detention':{theme:'Ký ức dưới sự đàn áp',lede:'Detention không cần ngôi trường đầy quái vật ngay từ phút đầu. Sự vắng người, đồ vật quen ở sai trạng thái và điều không được phép nói đã đủ tạo áp lực. Game đặt kinh dị bên cạnh một bối cảnh lịch sử cụ thể, để nỗi sợ không chỉ đến từ thứ siêu nhiên đang chờ ngoài hành lang.',chapters:[section('Ngôi trường giữ những điều từng bị buộc im lặng','Bối cảnh Đài Loan thời thiết quân luật đưa câu chuyện vào một môi trường mà phát ngôn và lòng tin có hậu quả. Các nhân vật và ký ức mở dần, khiến người chơi cần đọc lại điều đã thấy dưới một ngữ cảnh khác. Lịch sử không chỉ là tờ chú thích để làm game có vẻ nghiêm túc.','Detention dùng yếu tố dân gian và tín ngưỡng để diễn đạt nỗi sợ, nhưng không thể giản lược mọi hình ảnh thành quái vật cần né. Các vật và nghi thức có liên hệ với đời sống, khiến không gian quen trở nên ám ảnh vì nó mang ký ức.'),section('Câu đố làm đồ vật trở thành chứng tích','Tương tác point-and-click và các câu đố đưa người chơi kiểm tra đồ dùng, ghi chép và sự khác biệt trong môi trường. Việc tìm một vật phù hợp vừa phục vụ tiến trình vừa kéo mắt về một chi tiết có ý nghĩa trong câu chuyện.','Các đoạn tránh nguy hiểm thay nhịp đọc bằng một áp lực trực tiếp. Tuy nhiên, trọng tâm không phải làm chủ một hệ chiến đấu. Người muốn survival horror với quản lý vũ khí sâu sẽ thấy đây là trải nghiệm tập trung vào khám phá và diễn giải hơn.'),section('Ký ức không xuất hiện như một hồ sơ ngay ngắn','Những mảnh thông tin có thể mâu thuẫn với ấn tượng ban đầu, khiến người chơi tự điều chỉnh cách hiểu nhân vật. Bài này giữ kín các nút thắt vì sự thay đổi ấy là một phần quan trọng của cảm xúc, không chỉ là đáp án cuối câu đố.','Điều nên biết trước là nội dung có thể nặng, liên quan đàn áp, tội lỗi và mất mát. Một game ngắn không có nghĩa cường độ nhẹ. Nếu cần nghỉ giữa các phần, đó là cách hợp lý để cho những điều đang đọc có khoảng xử lý.'),section('Âm thanh khiến hành lang trở nên chật hơn','Hình vẽ và bảng màu giữ môi trường có chất vừa cụ thể vừa bất ổn. Âm thanh nhỏ có thể khiến một khoảng trống trở thành nơi cần chú ý, còn các biểu tượng tạo cảm giác câu chuyện nằm trong những vật đã quen từ trước khi người chơi tới.','Detention đáng được đọc theo bối cảnh của nó, thay vì đặt mọi cảnh vào một khuôn kinh dị chung. Chính sự gắn giữa đời sống học đường, ký ức lịch sử và thế giới siêu nhiên làm nỗi sợ có một địa chỉ riêng.')],verdict:'Detention khiến ngôi trường thành nơi lịch sử và ký ức không chịu nằm yên. Kinh dị hiệu quả vì nó gắn với những điều con người đã bị buộc phải chịu hoặc giấu, không chỉ với hình dáng của một bóng ma.',fit:'Thích horror có bối cảnh văn hóa, kể chuyện và câu đố point-and-click.',caution:'Nội dung lịch sử và cảm xúc nặng; ít hệ thống chiến đấu.'}
});
Object.assign(module.exports,{
'sanabi':{theme:'Ký ức giữa thành phố máy móc',lede:'Cánh tay móc biến một khoảng trống rất rộng thành đường đi. SANABI cho chuyển động cảm giác bay qua một thành phố, rồi dùng những khoảng dừng để đặt câu hỏi về điều đang kéo nhân vật về phía trước. Một cái tên tưởng là mục tiêu trả thù dần có sức nặng vượt khỏi một dấu đánh trên bản đồ.',chapters:[section('Mago là bối cảnh của một cuộc truy tìm cá nhân','Nhân vật bước vào một thành phố mang dấu của tập đoàn và máy móc, với quá khứ làm động lực. Những cuộc gặp, đặc biệt với Mari, tạo đối trọng cho sự cứng rắn của người đang theo một mục tiêu. Game đặt cảm xúc giữa các cảnh hành động, không chỉ giữ nó cho phần kết.','SANABI có những chuyển hướng quan trọng nên bài này không giải thích danh tính, ký ức hay ý nghĩa cuối của cái tên. Điều đáng biết là câu chuyện dành nhiều thời gian cho quan hệ và bối cảnh. Nếu chỉ muốn platformer chạy liên tục, các đoạn ấy sẽ là phần trải nghiệm cần chấp nhận.'),section('Móc dây là cách đọc khoảng cách','Khả năng bám và kéo người tới điểm thích hợp làm các màn được hiểu bằng những chuỗi đà. Một vị trí an toàn không nhất thiết là mặt đất; có thể là điểm để chuyển hướng và nối sang cú móc tiếp theo. Người chơi học nhìn môi trường như một mạng lưới có thể di chuyển.','Khi thao tác thành nhịp, việc vượt một khu vực tạo cảm giác rất khác nhảy giữa nền cố định. Nhưng giai đoạn đầu cần học cách canh vị trí và phản ứng. Một cú móc đúng đích chưa chắc đủ nếu bạn không biết nên tiếp tục đi về hướng nào khi tới đó.'),section('Thành phố đưa nguy hiểm vào chuỗi chuyển động','Chướng ngại và các cuộc chạm trán yêu cầu giữ sự chú ý trong lúc dùng móc. Game phát triển thử thách bằng cách làm môi trường can thiệp vào nhịp đã học, thay vì chỉ tăng chiều rộng khoảng trống. Tình huống tốt buộc người chơi sửa một chuỗi đang quen để nó thích nghi.','Điểm trở lại giúp thử tiếp nhưng không xóa việc một đoạn có thể cần nhiều lần làm quen. Nếu quá tập trung vào tốc độ, bạn dễ bỏ qua dấu hiệu của bước kế. Nhìn trước một điểm bám thường hữu ích hơn cố cứu một chuyển động sau khi đã lao đi sai hướng.'),section('Pixel và hội thoại tạo hai loại nhịp','Diện mạo đô thị cùng hoạt ảnh làm hành động có lực, trong khi các cuộc trò chuyện cho nhân vật có thời gian hiện ra ngoài năng lực chiến đấu. Sự đối lập giữa cơ thể rất hiệu quả và tâm trí mang nhiều điều chưa rõ là phần sức hút của SANABI.','Các cảnh truyện có thể dài so với độ gọn của một màn hành động. Đây không hẳn là nhược điểm chung, nhưng là khác biệt gu cần nói rõ. Game hợp khi bạn muốn cả chuyển động bằng móc và một câu chuyện có đủ khoảng để cảm xúc tích lại.')],verdict:'SANABI có một công cụ di chuyển rất nhận diện, nhưng không dùng nó để tránh kể chuyện. Những khoảng bay qua thành phố và những khoảng dừng cùng tạo một hành trình cần được giữ nguyên các bí mật lớn.',fit:'Thích grappling platformer và truyện cảm xúc xen hành động.',caution:'Có nhiều cảnh truyện, nội dung bạo lực và nhịp thao tác cần luyện.'},
'skul-the-hero-slayer':{theme:'Biến đổi vai trò bằng chiếc đầu',lede:'Skul nhỏ và không giống người hùng trên áp phích, nhưng chiếc đầu có thể đổi làm bộ xương nhận những cách đánh rất khác nhau. Câu hỏi của mỗi lượt không chỉ là nhặt được đồ mạnh hay không; nó là hai bộ kỹ năng đang có có thể giúp nhau thế nào khi căn phòng tiếp theo đã đông hơn.',chapters:[section('Đứng ở phía thường bị gọi là quái vật','Tiền đề đặt Skul vào việc cứu phe quỷ khỏi cuộc tấn công của con người. Sự đảo vai tạo một giọng nhẹ và một lý do để nhân vật nhỏ bước ra ngoài. Câu chuyện không chiếm phần lớn thời gian nhưng giúp cuộc chạy không chỉ là chuyến đi vô danh qua các phòng.','Đừng kỳ vọng một RPG nhiều nhánh vì game có một tiền đề khác thường. Skul tập trung hơn vào hình dạng của hành động. Phần hấp dẫn là xem một bộ xương có thể chuyển sang vai trò mới ngay trong cùng lượt, thay vì tích một cây kỹ năng cố định thật lâu.'),section('Hai chiếc đầu tạo một nhịp thay đổi','Mỗi đầu mang bộ khả năng và cách đánh riêng. Việc đổi giữa chúng cho phép chọn công cụ phù hợp với tình huống và tận dụng các hiệu ứng liên quan. Một cặp có thể hỗ trợ khoảng gần, một cặp khác làm việc với phép hoặc khoảng cách.','Thay đổi không chỉ là tăng chỉ số. Nó buộc bàn tay điều chỉnh tầm, thời gian chờ và thời điểm dùng kỹ năng. Đây là cơ hội thử nhiều kiểu hành động, nhưng cũng có nghĩa một lượt nhặt được đầu chưa quen có thể cần học lại ngay giữa hành trình.'),section('Vật phẩm cần được đọc như một tập hợp','Các hiệu ứng và tương tác hỗ trợ cách xây dựng lượt chơi. Chọn một món vì hợp kế hoạch có thể tốt hơn chọn chỉ vì hiếm. Game khuyến khích nhìn mối liên hệ giữa đầu đang dùng, khả năng đổi và những lợi ích từ vật phẩm.','Ngẫu nhiên khiến kế hoạch không luôn được trao đúng thứ cần. Đồng thời, màn hình nhiều hiệu ứng có thể làm khó việc biết điều gì vừa gây nguy hiểm. Người chơi cần học cả hệ thống chọn đồ lẫn hệ thống đọc đòn, không chỉ thuộc một chuỗi tấn công đẹp.'),section('Một phong cách vui không xóa độ khó','Hoạt ảnh và pixel art làm các hình dạng mới có cá tính. Nhịp nhanh tạo nhiều cơ hội cho chuỗi hành động liên tục, nhưng các cuộc chạm trán lớn có thể buộc bạn chậm lại để học. Các tùy chọn hỗ trợ hữu ích cho người muốn làm quen.','Lặp các lượt là nền tảng, nên ai muốn thấy cảnh mới sau mọi buổi chơi có thể nhanh thấy giới hạn. Skul hấp dẫn khi một lựa chọn đầu làm bạn tò mò đủ để trở lại những vùng đã đi, không chỉ khi game kể thêm một biến cố trong câu chuyện.')],verdict:'Skul dùng việc đổi đầu để làm thích ứng trở thành phần trung tâm của hành động. Niềm vui nằm trong thử các cặp kỹ năng và vật phẩm, với độ khó và sự ngẫu nhiên cần được chấp nhận từ đầu.',fit:'Thích roguelite, nhiều bộ kỹ năng và thử cách kết hợp nhân vật.',caution:'Nhiều hiệu ứng, ngẫu nhiên và lặp lượt; truyện không phải trọng tâm.'},
'a-space-for-the-unbound':{theme:'Tuổi học trò và sức khỏe tinh thần',lede:'Một thị trấn Indonesia cuối thập niên 1990 có thể bắt đầu bằng tiếng nói chuyện, quán nhỏ và một con mèo muốn được vuốt. A Space for the Unbound để những điều thân thuộc ấy hiện ra trước khi sự kỳ lạ bước vào. Nhờ vậy, khi cảm xúc trở nên quá lớn, bạn biết chúng đang đe dọa một đời sống cụ thể, không chỉ một thế giới tưởng tượng.',chapters:[section('Atma và Raya có những mong muốn rất gần','Những ngày cuối tuổi học trò và quan hệ giữa hai nhân vật tạo nền cho hành trình. Thị trấn có đồ vật, thói quen và người dân làm bối cảnh mang một địa chỉ văn hóa rõ. Những chi tiết nhỏ khiến câu chuyện không thể thay bằng một thị trấn bất kỳ mà giữ nguyên cảm giác.','Yếu tố siêu nhiên phát triển từ đời thường, thay vì phủ lên nó ngay từ đầu. Bài này không kể các nút thắt, vì việc hiểu cảm xúc và quan hệ qua những lần gặp mới là phần thưởng chính. Điều nên biết là game có các chủ đề lo âu, trầm cảm và tổn thương.'),section('Spacedive biến nội tâm thành nơi để đi qua','Khả năng bước vào tâm trí tạo một cách khám phá những vấn đề nhân vật đang mang. Các câu đố và tình huống dùng hành động để diễn đạt điều khó nói, khiến phần siêu nhiên có chức năng kể chuyện. Nó không chỉ là sức mạnh thuận tiện để mở cửa.','Cách tiếp cận này cần được đọc cùng những cuộc trò chuyện bên ngoài. Một hình ảnh trong nội tâm không phải lúc nào cũng là thông tin có thể tóm thành một câu. Người chơi được khuyến khích nối những biểu hiện ấy với đời sống của người mình vừa gặp.'),section('Những việc nhỏ giữ thị trấn có chất sống','Đi quanh, tìm đồ và các hoạt động xen kẽ tạo nhịp một cuộc phiêu lưu đời thường. Chúng cho thời gian để những người và nơi chốn trở nên quen. Khi chuyện lớn xảy ra, sự thân thuộc đó giúp cảm xúc có điểm bám.','Một số việc có thể thành cảm giác đi lại hoặc thử quá nhiều thao tác nếu bạn chỉ muốn câu chuyện tiến nhanh. Game không luôn giữ cường độ cao. Sự chậm ở đầu là một phần cấu trúc, nhưng người chơi vẫn nên biết đây không phải visual novel chỉ cần ngồi đọc liên tục.'),section('Pixel art giữ những ký ức có địa chỉ','Kiến trúc, màu và các chi tiết đời sống tạo một Indonesia không chỉ tồn tại như nhãn quốc gia trong danh mục. Âm nhạc giúp những khoảng bình thường có chỗ yên, trước khi câu chuyện đổi sắc. Các con mèo và những cuộc gặp nhỏ tạo sự dịu dàng không cần phủ nhận nội dung nặng.','Game nên được chọn khi bạn sẵn sàng cho một hành trình cảm xúc. Dừng nghỉ khi nội dung khó tiếp nhận là điều hợp lý. Vẻ ngoài ấm không bảo đảm câu chuyện luôn ấm, và chính sự tương phản đó khiến đời sống nhỏ ở thị trấn có sức nặng.')],verdict:'A Space for the Unbound dùng một thị trấn cụ thể để giữ những cảm xúc lớn khỏi trở thành khái niệm chung. Yếu tố kỳ ảo có giá trị vì nó nối vào đời sống của Atma, Raya và những người quanh họ.',fit:'Thích phiêu lưu kể chuyện, bối cảnh Indonesia và diễn đạt nội tâm bằng hình ảnh.',caution:'Có chủ đề sức khỏe tinh thần nặng, các đoạn chậm và việc tìm đồ.'}
});
Object.assign(module.exports,{
'coffee-talk':{theme:'Lắng nghe và khác biệt',lede:'Quán mở vào đêm mưa ở một Seattle có cả người và những giống loài kỳ ảo. Khách không cần bạn cứu thành phố. Họ cần một đồ uống và thời gian để nói điều đang vướng. Coffee Talk giữ quy mô ấy đủ nhỏ để một chuyện về công việc hoặc tình yêu có thể làm cả ca thay sắc.',chapters:[section('Đời sống kỳ ảo vẫn có những va chạm rất quen','Khác biệt về giống loài và quan hệ gia đình tạo ngữ cảnh cho các cuộc trò chuyện. Bối cảnh không chỉ dùng hình dáng fantasy để làm quán nhiều màu; nó cho người chơi một cách nhìn các vấn đề đời thường qua một khoảng cách vừa đủ.','Bạn ở vị trí barista, thường lắng nghe nhiều hơn can thiệp trực tiếp. Nhân vật trở lại giúp những mẩu chuyện có thời gian phát triển và được đọc cùng những gì đã nói trước đó. Quán trở thành một điểm hẹn, không chỉ một phông nền thay khách sau mỗi màn.'),section('Ba nguyên liệu tạo một việc nhỏ để làm giữa câu chữ','Pha đồ uống yêu cầu chọn thành phần và thử công thức. Một yêu cầu có thể rất cụ thể, một yêu cầu có thể diễn đạt bằng cảm giác muốn có. Thao tác này giữ người chơi tham gia nhưng không cố biến trải nghiệm thành mô phỏng kinh doanh phức tạp.','Latte art và việc thử đồ uống thêm một khoảng thực hành nhẹ. Tuy nhiên, người tìm chiều sâu quản lý quán hoặc nhiều quyết định kinh tế sẽ không thấy điều ấy ở đây. Coffee Talk dùng công việc để tạo nhịp lắng nghe, không dùng lắng nghe làm thời gian chờ tăng doanh thu.'),section('Đồ uống đúng có thể mở một cuộc trò chuyện khác','Lựa chọn đồ uống liên hệ với diễn biến và phản ứng, tạo cảm giác người phía sau quầy có vai trò. Nhưng phạm vi đó vẫn tiết chế. Bạn không điều khiển mọi quyết định của khách bằng một bảng đáp án, và câu chuyện dành chỗ cho họ tự thể hiện.','Sự nhẹ nhàng không đồng nghĩa mọi đề tài đều dễ. Các vấn đề về quan hệ, kỳ vọng và công việc có thể gợi trải nghiệm cá nhân. Game có nhịp thích hợp cho việc đọc từng ca, thay vì phải hoàn tất thật nhanh để chứng minh đã tìm hết mọi nhánh.'),section('Tiếng mưa là một phần của căn phòng','Pixel art, âm nhạc lofi và nền mưa làm không gian có chất ấm. Vì địa điểm quen được giữ qua nhiều lượt gặp, người chơi dần nhận ra quán như một nơi có thói quen. Sự thân thuộc hỗ trợ câu chuyện mà không cần xây thêm bản đồ lớn.','Một số đối thoại có thể dài và cơ chế đơn giản có thể khiến người chỉ thích hành động thấy ít việc để làm. Nếu mục đích là dành một buổi tối cho vài câu chuyện và một nhịp yên, chính sự đơn giản giúp game giữ tập trung.')],verdict:'Coffee Talk cho sự chú ý một nơi chốn: chiếc quầy barista trong đêm mưa. Đồ uống và âm nhạc tạo nhịp, còn các khách quen làm quán có lý do để mở lại. Nó phù hợp với người muốn lắng nghe hơn muốn quản lý.',fit:'Thích visual novel nhẹ, chuyện đời thường và không khí quán cà phê.',caution:'Nhiều hội thoại, ít hệ thống quản lý và nhịp chậm.'},
'raji-an-ancient-epic':{theme:'Thần thoại và tình thân',lede:'Raji bước qua một khung cảnh có thể khiến bạn dừng lại trước khi nghĩ tới trận đánh kế tiếp. Đền đài, họa tiết và những đoạn kể về thần linh làm thế giới có chất văn hóa rất rõ. Nhưng động lực của người đi trong đó vẫn gần gũi: một người chị muốn tìm lại em trai.',chapters:[section('Một cuộc tìm kiếm đặt giữa những câu chuyện lớn','Raji và Golu đưa tình thân vào trung tâm của hành trình. Yếu tố thần thoại và các thế lực siêu nhiên nâng quy mô, nhưng mục tiêu cá nhân giữ nhân vật không tan vào một bản giới thiệu thế giới. Bạn biết vì sao cô tiếp tục ngay khi môi trường ngày càng xa lạ.','Game dùng các đoạn kể và hình ảnh để đưa người chơi vào ngữ cảnh. Đây không phải một mô phỏng tổng quát mọi truyền thống Ấn Độ; nó là một tác phẩm có lựa chọn nghệ thuật cụ thể. Đọc các lựa chọn ấy trong cách môi trường được xây sẽ có ích hơn chỉ xem chúng như phong cách khác lạ.'),section('Vũ khí và di chuyển phải làm việc cùng nhau','Chiến đấu cho Raji các cách xử lý đối thủ và tận dụng không gian. Nhịp di chuyển cùng các động tác đặc thù giúp cảnh hành động có chất riêng. Đọc tầm đòn và chọn khoảng trống vẫn là nền tảng để giữ cuộc chạm trán không chỉ thành chuỗi nút bấm.','Tuy nhiên, độ sâu và phản hồi không phải lúc nào cũng đồng đều với sức mạnh của mỹ thuật. Người tìm một action game để luyện hệ thống cực lâu có thể thấy giới hạn. Nên chọn game vì cả hành trình và không gian, thay vì kỳ vọng chiến đấu một mình gánh toàn bộ trải nghiệm.'),section('Kiến trúc tạo hướng nhìn cho người chơi','Các công trình và góc máy khiến môi trường có cảm giác như những cảnh được sắp đặt để kể chuyện. Khi đi qua cầu, sân và những lớp kiến trúc, người chơi nhìn thấy quan hệ giữa con người nhỏ và cấu trúc lớn. Cảnh quan không chỉ để đặt đối thủ lên trên.','Nhưng góc nhìn được kiểm soát cũng có thể làm một tình huống di chuyển khó đọc hơn mong muốn. Nhịp khám phá khá tuyến tính, nên người muốn tự đi bất kỳ hướng nào sẽ thấy phạm vi nhỏ. Sự dẫn dắt này giúp mỹ thuật nổi bật, đồng thời giới hạn tự do.'),section('Mỹ thuật là phần lý do nên ở lại','Hình ảnh lấy cảm hứng từ các truyền thống nghệ thuật và kiến trúc Ấn Độ, cùng phần âm nhạc tạo một bản sắc khác với fantasy chung chung. Những khoảng dừng để nghe hoặc nhìn không phải thời gian vô ích giữa hai trận; chúng là phần game làm tốt.','Hành trình không quá dài và có những chỗ chiến đấu hoặc di chuyển chưa thật mượt. Điều đáng cân nhắc là bạn muốn một hệ thống hoàn hảo hay một chuyến đi có diện mạo và nguồn cảm hứng rõ. Raji có giá trị ở khả năng mở một không gian văn hóa bằng một câu chuyện tình thân dễ hiểu.')],verdict:'Raji nối một cuộc tìm em với thế giới thần thoại và kiến trúc được chăm chút. Mỹ thuật là sức mạnh rõ nhất; chiến đấu và di chuyển có giới hạn cần nói thẳng, nhưng không làm nguồn cảm hứng riêng của hành trình biến mất.',fit:'Muốn hành động phiêu lưu tuyến tính với mỹ thuật và thần thoại Ấn Độ.',caution:'Hành trình ngắn; chiến đấu và góc nhìn có chỗ chưa đồng đều.'},
'rusty-lake-hotel':{theme:'Nghi thức trong điều phi lý',lede:'Khách sạn đã có khách, người phục vụ đã sẵn sàng và bữa tối còn thiếu nguyên liệu. Rusty Lake Hotel làm một khung dịch vụ quen thuộc nhận vẻ rất sai bằng những nhân vật đầu thú và cách nói chuyện bình thản. Bạn biết nơi này có luật; điều khó chịu là chưa biết luật ấy xem chuyện gì là bình thường.',chapters:[section('Năm vị khách có năm căn phòng để đọc','Cấu trúc chia theo phòng giúp cuộc phiêu lưu có từng đơn vị rõ. Mỗi khách và môi trường của họ tạo một nhóm câu đố riêng, nhưng các phần cùng nằm trong nghi thức của khách sạn. Sự lặp về khung làm điều khác thường ở từng phòng nổi bật.','Câu chuyện dùng hình ảnh, lời ngắn và sự kiện phi lý thay vì giải thích mọi mối liên hệ của vũ trụ Rusty Lake. Người mới có thể theo khung công việc trước mắt, còn những câu hỏi lớn hơn tiếp tục được giữ mở. Bài này không kể các nguyên liệu hay cách hoàn tất từng bữa.'),section('Point-and-click yêu cầu đọc vật và thử quan hệ','Quan sát, thu thập và dùng đồ đưa người chơi đi qua các câu đố. Một vật tưởng nhỏ có thể liên hệ với một cơ chế ở góc khác. Game thường giữ mỗi không gian gọn, giúp kiểm tra giả thuyết mà không phải đi qua một bản đồ quá lớn.','Tuy nhiên, logic siêu thực không luôn giống logic đời thường. Có đoạn thử nghiệm và quan sát phản hồi quan trọng hơn đoán theo công dụng thật của đồ. Nếu thích câu đố chỉ có một lời giải tự nhiên có thể suy trước đầy đủ, một số tình huống có thể làm bạn thấy phải mò.'),section('Bữa tối tạo tiến trình bằng một công việc bất thường','Khung chuẩn bị món ăn nối các căn phòng vào một quá trình có thứ tự. Người chơi có mục tiêu rõ ở quy mô nhỏ trong khi ý nghĩa của mục tiêu lại gây nghi ngờ. Sự tương phản giữ câu chuyện vừa có cấu trúc vừa không hoàn toàn đáng tin.','Các điều kiện liên quan những nguyên liệu phụ có thể khuyến khích xem kỹ, nhưng cũng dễ biến lần đầu thành việc tra checklist. Hãy ưu tiên hiểu nhịp riêng của từng phòng trước. Cảm giác khó chịu đến từ việc tự nhận ra quan hệ giữa khách và bữa ăn, không phải từ việc biết trước mọi vị trí vật phẩm.'),section('Lời nói bình thản làm kinh dị có một giọng khác','Hình vẽ, âm nhạc và cách các nhân vật phản ứng giữ một vẻ trang trọng ngay trong điều kỳ quái. Game không liên tục hét rằng bạn đang ở nơi đáng sợ. Chính sự bình thường hóa ấy làm một sự kiện nhỏ có thể trở nên ám ảnh.','Quy mô ngắn và nội dung rùng rợn là hai điều nên biết. Rusty Lake Hotel không cung cấp một cuộc điều tra dài với giải thích khép kín. Nó cho vài căn phòng đủ chặt để xây một nghi thức, rồi để ý nghĩa của nghi thức ấy tiếp tục gây câu hỏi.')],verdict:'Rusty Lake Hotel làm point-and-click có sức hút bằng giọng bình thản giữa sự phi lý. Cấu trúc từng phòng tạo một hành trình gọn, còn các khoảng chưa giải thích giữ khách sạn không trở thành một bộ câu đố vô hồn.',fit:'Thích room escape, humor đen và kinh dị siêu thực.',caution:'Ngắn, có logic kỳ quái và một số điều kiện dễ bỏ sót.'}
});
